    [358] = {n="Profanadores", d="Mata a los asaltatumbas Putrepellejo y a los bastardos Putrepellejo.\nLlévale 8 icores embalsamantes al magistrado Sevren de Rémol.", tgo={{"Asaltatumbas Putrepellejo"}, {"Bastardo Putrepellejo"}, {"Gnoll Putrepellejo", "Bastardo Putrepellejo", "Asaltatumbas Putrepellejo"}}},
