    [365] = {n="Campos de pena", d="Roba 10 calabazas de la plantación que encontrarás en dirección oeste, justo al norte de Camposanto, y llévaselas al boticario Johaan a Rémol.", objs={"Calabaza de Tirisfal"}},
    [367] = {n="Una nueva Peste", d="El boticario Johaan de Rémol quiere que recojas 5 viales de sangre de can oscuro.", tgo={{"Can oscuro decrépito", "Can oscuro maldito", "Can oscuro voraz"}}},
