    [370] = {n="En guerra con la Cruzada Escarlata", d="El ejecutor Zygand de Rémol quiere que mates al capitán Perrine, a 3 zelotes Escarlata y a 3 misioneros Escarlata.", tgo={{"Capitán Perrine"}, {"Zelote Escarlata"}, {"Misionero Escarlata"}}},
    [371] = {n="En guerra con la Cruzada Escarlata", d="El ejecutor Zygand de Rémol te ha encargado que mates al capitán Vachon y a 5 frailes Escarlata.", tgo={{"Capitán Vachon"}, {"Fraile Escarlata"}}},
    [372] = {n="En guerra con la Cruzada Escarlata", d="El ejecutor Zygand de Rémol quiere que asesines al capitán Melrache y a sus dos guardaespaldas.", tgo={{"Capitán Melrache"}, {"Guardaespaldas Escarlata"}}},
    [374] = {n="Prueba de defunción", d="Llévale 10 anillos con la insignia escarlata al Guardia de la Muerte Burgess de Rémol.", tgo={{"Guerrero Escarlata", "Misionero Escarlata", "Zelote Escarlata", "Fraile Escarlata", "Neófita Escarlata", "Vanguardia Escarlata", "Guardaespaldas Escarlata", "Capitán Perrine"}}},
    [375] = {n="El frío de la muerte", d="Llévale 5 pelambres de Murciumbrío y un hilo burdo a Gretchen Dedmar, que está en Rémol.", tgo={{"Murciumbrío superior", "Murciumbrío vampírico"}, {}}},
    [376] = {n="Los Malditos", d="La novicia Elreth requiere 6 garras de carroñero y 6 alas de murciumbrío.", tgo={{"Carroñero joven", "Carroñero pulgoso"}, {"Murciumbrío", "Murciumbrío sarnoso", "Murciélago Timbralevín"}}},
    [380] = {n="Hoya Nocturácnidas", d="El ejecutor Arren quiere que mates 10 nocturánidas jóvenes y 8 arañas nocturánidas.", tgo={{"Nocturácnida joven"}, {"Araña nocturácnida"}}},
    [381] = {n="La Cruzada Escarlata", d="Lleva al ejecutor Arren 12 bandas Escarlata de conversos Escarlata y de iniciados Escarlata.", tgo={{"Converso Escarlata", "Iniciado Escarlata", "Meven Korgal"}}},
    [382] = {n="El mensajero rojo", d="Mata a Meven Korgal, el mensajero, en el campamento de los Cruzados y vuelve a comunicar al ejecutor Arren cualquier información que encuentres.", tgo={{"Meven Korgal"}}},
    [383] = {n="Información decisiva", d="Ve a Rémol y entrega los documentos de la Cruzada Escarlata al ejecutor Zygand."},
    [398] = {n="SE BUSCA: Ojo de cresa", d="Mata a Ojo de cresa y llévale su garra al ejecutor Zygand de Rémol para obtener una recompensa.", tgo={{"Ojo de cresa"}}},
    [404] = {n="Una tarea pútrida", d="Llévale 7 garras podridas al Guardia de la Muerte Dillinger de Rémol.", tgo={{"Muerto en podredumbre", "Cuerpo devastado"}}},
    [407] = {n="Campos de pena", d="Llévale la calabaza envenenada al zelote Escarlata capturado que está encerrado en el sótano del Mesón La Horca."},
    [408] = {n="La Cripta de la Familia", d="Mata a 8 ancestros gemebundos y a 8 ancestros en podredumbre.\nMata al capitán Dargol y llévale su calavera al magistrado Sevren de Rémol.", tgo={{"Ancestro gemebundo"}, {"Ancestro en podredumbre"}, {"Capitán Dargol"}}, star={"Bastón Leñoscuro", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}},
