    [423] = {n="La locura de Arugal", d="Lleva 6 grilletes de glotón y 3 grilletes de almanegra a Dalar Tejealba en El Sepulcro.", tgo={{"Glotón Furia Lunar"}, {"Almanegra Furia Lunar"}}},
