    [4290] = {n="La comida de Lar'korwi", d="Encuentra la última presa muerta de Lar'korwi y roba un trozo de trillanodonte muerto, y después ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro.", objs={"Cadáver reciente de trillanodonte"}},
    [4291] = {n="Un aroma irresistible para Lar'korwi", d="Llévale 2 glándulas de feromonas de ravasaurio a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro.", tgo={{"Compañera de Lar'korwi"}}},
    [4292] = {n="El cebo para Lar'korwi", d="Utiliza el contenido de la faltriquera de Torwa para atraer la presencia de Lar'korwi y derrótalo. Después llévale la cabeza de Lar'korwi a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro.", tgo={{"Lar'korwi"}}},
    [4296] = {n="La tablilla de los Siete", d="Lleva la trascripción de tablilla a Maxwort Suprandor en las Estepas Ardientes.", objs={"Tablilla de los Siete"}},
