    [4449] = {n="Atrapado", d="Mata a 8 geólogos Hierro Negro y lleva 15 paños de seda a la persona encerrada en las letrinas de La Garganta de Fuego.", tgo={{"Geólogo Hierro Negro"}, {}}, objs={"Granito de Alterac", "Cofre ajado", "Cofre macizo"}},
    [4489] = {n="Invoca un corcel vil", d="Habla con Strahad Farsan en Trinquete."},
    [4490] = {n="Invoca un corcel vil", d="Habla con Strahad Farsan en Trinquete para aprender a invocar a un corcel vil."},
    [4491] = {n="Un poco de ayuda de mis amigos", d="Lleva a Ringo con Spraggle Frock en el Refugio de Marshal.\nSi Ringo se desmaya utiliza la cantimplora de Spraggle para revivirlo."},
