    [4496] = {n="Que jungla tan chunga", d="Llévale una glándula secretora de olor Gorishi y 5 muestras de la tierra de Un'Goro al alquimista Morterozugg de Gadgetzan.", tgo={{"Avispa Gorishi", "Trabajador Gorishi", "Atracador Gorishi", "Aguijonero Gorishi", "Tunelador Gorishi", "Guardia de la colmena Gorishi", "Reina de la colmena Gorishi"}, {}}, objs={"Montón de porquería de Un'Goro"}},
    [4502] = {n="Actividad volcánica", d="Lleva 9 muestras de ceniza de los elementales de fuego del Cráter de Un'Goro a Liv Rizzlefix a Trinquete.", tgo={{"Elemental agostador", "Llamarada viviente", "Correfuego", "Invasor de fuego", "Barón Charr"}}},
    [4503] = {n="El aparato volador de Shizzle", d="Recoge 8 escamas de diemetradón palmeadas y 8 escamas de pterrordáctilo palmeadas para Shizzle, en el Refugio de Marshal.", tgo={{"Diemetradón joven", "Diemetradón", "Diemetradón viejo"}, {"Pterrordáctilo volantón", "Pterrordáctilo", "Pterrordáctilo demenciado"}}},
    [4504] = {n="Superpegajoso", d="Reúne 12 muestras de alquitrán muy pegajoso para Tran'rek de Gadgetzan.", tgo={{"Bestia de alquitrán", "Rondador de alquitrán", "Señor de alquitrán", "Trepador de alquitrán"}}},
    [4505] = {n="Pozo de corrupción", d="Recoge una muestra de agua corrupta de la Poza de la Luna de los sátiros Fuego de Jade y llévasela a Winna Riessgo al Puesto del Veneno.", objs={"La Poza de la Luna corrupta"}},
    [4506] = {n="Sables corruptos", d="Lleva el gatito de Winna a la poza de la luna corrupta, libéralo y llévaselo de nuevo a Winna.\nHaz clic en el gato para liberarlo y devolvérselo a Winna cuando estés cerca de ella."},
    [4521] = {n="Guardianes salvajes", d="Trull Fallarruina de Frondavil quiere que mates 15 lechubestias enfurecidas y 15 lechubestias pulgosas.", tgo={{"Lechubestia enfurecida"}, {"Lechubestia pulgosa"}}},
    [4542] = {n="Mensaje para el Poblado Viento Libre", d="Entrégale el mensaje urgente al vigiarrisco Cuerno Largo en el Poblado Viento Libre."},
    [4641] = {n="Tu lugar en el mundo", d="Habla con Gornek. Recuerda que Kaltunk marcó en tu mapa su ubicación y que te mencionó que Gornek reside en El Cubil, un edificio que está al oeste.|n|n"},
    [4724] = {n="La maestra de la manada", d="Mata a Halycon, la maestra de la manada de los huargos Hacha de Sangre.", tgo={{"Halycon"}}},
    [4726] = {n="Esencia de cría", d="Llévale 8 esencias de cría y el Draco-Incarcinatrix 900 a Tinkee Vaporio en el Peñasco Llamarada, en Las Estepas Ardientes.", objs={"Esencia de cría"}},
    [4729] = {n="Las mascotas exóticas de Kibler", d="Viaja hasta la Cumbre de Roca Negra y encuentra cachorros de huargo Hacha de Sangre. Usa la jaula para transportar a esas feroces fierecillas. Llévale a Kibler 1 cachorro de huargo enjaulado."},
    [4737] = {n="Buscando a Menara Nadiz", d="Habla con Menara Nadiz en Los Baldíos."},
    [4739] = {n="Buscando a Menara Nadiz", d="Habla con Menara Nadiz en Los Baldíos."},
    [4742] = {n="El sello de ascensión", d="Encuentra las 3 gemas del mando: La gema de Espina Ahumada, la gema de Cumbrerroca y la gema de Hacha de Sangre. Llévaselas, junto con el sello de ascensión sin adornar a Vaelan.\nLos generales, como te dijo Vaelan, son: el maestro de guerra Voone de los Espina Ahumada, el alto señor Omokk de los Cumbrerroca y el señor supremo Vermiothalak de los Hacha de Sangre.", tgo={{"Alto señor Omokk"}, {"Maestro de guerra Voone"}, {"Señor supremo Vermiothalak"}, {"Bruto Escudo del Estigma", "Argos Escudo del Estigma", "Acólito Escudo del Estigma", "Intendente Escudo del Estigma", "Legionario Escudo del Estigma", "Vinculador de hechizo Escudo del Estigma", "Alto señor Omokk", "Mago de batalla Cumbrerroca"}}},
    [4743] = {n="El sello de ascensión", d="Viaja a la Ciénaga de Fuego en Marjal Revolcafango. Encuentra al anciano draco Brasaliza y derrótalo sin contemplaciones hasta doblegar su voluntad.\nEste es el preciso momento en el que debes colocar el Sello de ascensión sin forjar ante la colosal bestia. Debes entonces ser rápido en usar el orbe de energía dracónica sobre su debilitada forma y reclamar el dominio sobre sus facultades mentales. ¡Controla la bestia y dirige las llamas del Vuelo Negro sobre el Sello de ascensión sin forjar!", objs={"Sello de ascensión forjado"}},
    [4767] = {n="Jinete del viento", d="Consigue 10 huevos de dracoleón de Nido Alto para Elu en el Poblado Viento Libre.", objs={"Huevo de dracoleón de Nido Alto"}},
    [4768] = {n="La tablilla de Rocanegra", d="Llévale la tablilla de Rocanegra a la maga oscura Vivian Lagrave en Kargath.", objs={"Tablilla de Rocanegra"}},
    [4769] = {n="Vivian Lagrave y la tablilla de Rocanegra", d="Habla con la maga oscura Vivian Lagrave."},
    [4770] = {n="De vuelta a casa", d="Saca a Pao'ka Monte Presto de Nido Alto y después habla con Motega Pirocabello en Campamento del Tramo Blanco."},
    [4781] = {n="Los componentes para la toga de sangre dorada encantada", d="Llévale un lingote de oro a Xizk Cortefino en la Vega de Tuercespina.", objs={"Cofre ajado", "Cofre macizo", "Caja fuerte de la Alianza"}},
    [4782] = {n="Los componentes para la toga de sangre dorada encantada", d="Regresa junto a Menara Nadiz en Los Baldíos."},
    [4783] = {n="Los componentes para la toga de sangre dorada encantada", d="Llévale 10 viales de sangre Odio Feroz y 1 piedra Infernal inferior a Menara Nadiz en Los Baldíos.", tgo={{"Pícaro Odio Feroz", "Tramposo Odio Feroz", "Jurapenas Odio Feroz", "Traidor Odio Feroz", "Acechasombras Odio Feroz", "Clamainferno Odio Feroz", "Príncipe Kellen"}, {"Infernal inferior", "Guardián del portal de demonios"}}},
    [4784] = {n="Los componentes para la toga de sangre dorada encantada", d="Llévale unos hilos finos de oro, 2 trozos de ascuas humeantes y 1 fragmento de alma a Menara Nadiz en Los Baldíos.", tgo={{"Xizk Cortefino"}, {"Exiliado ardiente"}, {}}},
    [4785] = {n="Hilo de oro refinado"},
    [4786] = {n="Toga terminada", d="Espera a que Menara Nadiz complete tu túnica y vuelve entonces a hablar con ella.", tgo={{"Menara Nadiz"}}, star={"Toga de sangre dorada encantada", {"WARLOCK"}}},
    [4787] = {n="El huevo antiguo", d="Llévale el huevo antiguo a Yeh'kinya, que está en Tanaris.", objs={"Huevo antiguo"}},
    [4808] = {n="Felnok Acerovera", d="Entrega la carta de Tinkee a Felnok Acerovera."},
    [4809] = {n="Cuernos de Orvallo", d="Lleva 8 cuernos de Orvallos intactos a Felnok Acerovera.", tgo={{"Volantón Viento Gélido", "Quimera Viento Gélido", "Devastador Viento Gélido"}}},
    [4810] = {n="Regresa junto a Tinkee", d="Llévale la talega de Felnok a Tinkee Vaporio en Las Estepas Ardientes."},
    [4821] = {n="Un huevo extraño", d="Devuélvele el huevo extraño a Hagar Pezuña del Rayo, que está en el Poblado Viento Libre.", objs={"Huevo extraño"}},
    [4841] = {n="Apaciguar al centauro", d="Mata a 12 exploradores Galak, 10 retadores Galak y 6 cazavientos Galak, y después ve a ver de nuevo al vigiarrisco Cuerno Largo al Poblado Viento Libre.", tgo={{"Explorador Galak"}, {"Retador Galak"}, {"Cazavientos Galak"}}},
    [4842] = {n="Fuentes extrañas", d="Sigue las indicaciones de Donova Cubilnevado y vuelve a informarle."},
    [4862] = {n="Bestia amaestrada", d="Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler.\nYo diría que se pueden encontrar estos huevos cerca de arañas.", objs={"Huevo de araña de la cumbre"}},
    [4865] = {n="Venganza", d="Infórmale de tus hallazgos a Motega Pirocabello."},
    [4881] = {n="Complot de asesinato", d="Avisa a Kanati Nube Gris, en el Campamento del Tramo Blanco, acerca de la conspiración para acabar con su vida."},
    [4903] = {n="La orden del Señor de la Guerra", d="Mata al alto señor Omokk, al maestro de guerra Voone y al señor supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión.", tgo={{"Señor supremo Vermiothalak"}, {"Alto señor Omokk"}, {"Maestro de guerra Voone"}, {}}, objs={"Documentos inadvertidos"}},
    [4904] = {n="Al fin libre", d="Saca a Lakota Son del Viento de Cumbre de la Nube Negra y después habla con Thalia Ocultaámbar, que está en el Poblado Viento Libre."},
    [4921] = {n="Perdida en la batalla", d="Encuentra a la esposa de Mankrik y llévala a El Cruce.", tgo={{"Cadáver apaleado"}}},
    [4941] = {n="La sabiduría de Eitrigg", d="Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall.\nRecuerdas haber visto a Eitrigg en la Cámara de Thrall."},
    [4961] = {n="La purificación del orbe de Orahil", d="Mata al demonio del orbe y luego habla con Tabetha.", tgo={{"Demonio del orbe"}}},
    [4962] = {n="Fragmento de can manáfago", d="Coge el rubí de Felhas y úsalo en uno de los canes manáfagos de Desolace. Cuando lo consigas, llévale el rubí de Felhas y el espíritu del can manáfago encarcelado a Menara Nadiz en Los Baldíos.", tgo={{"Devorador de maná"}}},
    [4963] = {n="Fragmento de infernal", d="Coge la esmeralda de Infus y úsala en uno de los infernales de Desolace. Cuando lo consigas, llévale la esmeralda de Infus y el espíritu del infernal encarcelado a Menara Nadiz en Los Baldíos.", tgo={{"Infernal inferior"}}},
    [4964] = {n="El orbe completo de Dar'Orahil", d="Espera a Menara Nadiz para completar el orbe de Dar'Orahil y vuelve entonces a hablar con ella.", tgo={{"Menara Nadiz"}}},
    [4966] = {n="Defensa de Kanati Nube Gris", d="Defiende a Kanati Nube Gris contra el ataque de los centauros.", tgo={{"Asesino Galak"}}},
    [4967] = {n="El conocimiento del orbe de Orahil", d="Habla con Menara Nadiz en Los Baldíos."},
    [4969] = {n="El conocimiento del orbe de Orahil", d="Habla con Menara Nadiz en Los Baldíos."},
    [4971] = {n="Una cuestión de tiempo", d="Utiliza el desplazador temporal junto a uno de los silos de Andorhal y saca a la luz los parásitos temporales.\nMata a 15 parásitos temporales y devuélvele el desplazador temporal a Cromi en la posada de Andorhal, en las Tierras de la Peste del Oeste.", tgo={{"Parásito temporal"}}},
    [4972] = {n="Contar el tiempo", d="Localiza 5 relojes de Andorhal, los encontrarás en cajas fuertes entre las ruinas de la ciudad. Cuando los tengas regresa con Cromi, en la posada de Andorhal, en las Tierras de la Peste del Oeste.", objs={"Arcón pequeño"}},
    [4974] = {n="¡Por la Horda!", d="Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Lleva su cabeza a Orgrimmar.", tgo={{"Jefe de Guerra Rend Puño Negro"}}},
    [4975] = {n="El orbe completo de Noh'Orahil", d="Espera a Menara Nadiz para completar el orbe de Noh'Orahil y vuelve entonces a hablar con ella.", tgo={{"Menara Nadiz"}}},
    [4976] = {n="Devolver el orbe purificado", d="Llévale el orbe infernal limpio a Menara Nadiz en Los Baldíos."},
    [4981] = {n="La espía Bijou", d="Viaja hasta la Cumbre de Roca Negra y averigua qué le ha ocurrido a Bijou."},
    [4982] = {n="Las pertenencias de Bijou", d="Encuentra las pertenencias de Bijou y devuélveselas. Recuerdas que ella mencionó haberlas ocultado en la planta baja de la ciudad.", objs={"Pertenencias de Bijou"}},
    [4983] = {n="El informe de reconocimiento de Bijou", d="Llévale el informe de reconocimiento de Bijou al maestro mayor Lexlort en Kargath."},
    [4984] = {n="La naturaleza también sufre", d="Destruye 8 lobos malsanos y regresa con Mulgris Río Hondo en El Tormento, en las Tierras de la Peste del Oeste.", tgo={{"Lobo malsano"}}},
    [4985] = {n="La naturaleza también sufre", d="Destruye 8 pardos malsanos y regresa con Mulgris Río Hondo en El Tormento, en las Tierras de la Peste del Oeste.", tgo={{"Oso pardo malsano"}}},
    [5021] = {n="Más vale tarde que nunca", d="Entre lamentos, la mujer fantasmal recordaba tener que entregar un paquete. Según ella estaba junto a su caballo. No puedes entender dónde está el caballo o dónde había que entregar el paquete."},
    [5023] = {n="Más vale tarde que nunca", d="Consulta con los supervisores reales de Entrañas para averiguar el paradero de Jeremiah Piedra Mácula. Suele haber un oficial del censo junto a la oficina de registro de hermandades y tabardos."},
    [5041] = {n="Suministros para El Cruce", d="Encuentra los cajones de suministros en El Cruce y devuélvelos a Thork en los Baldíos.", objs={"Cajones de suministros de El Cruce"}},
    [5049] = {n="La depre de Jeremiah", d="Encuentra a Jeremiah Payson en Entrañas y averigua si en realidad es Jeremiah Piedra Mácula. Si es así, quizás quiera el paquete que Janice Piedra Mácula preparó para él."},
    [5050] = {n="Talismán de buena suerte", d="Devuelve a Janice Piedra Mácula en las Tierras de la Peste del Oeste su Medio talismán de buena suerte."},
    [5051] = {n="Dos mitades hacen una", d="Localiza la otra mitad del talismán de la suerte en algún lugar del Campo de Piedramácula, en las Tierras de la Peste del Oeste, y recomponlo.\nDale el talismán de la suerte a Janice Piedra Mácula en la Granja de Piedra Mácula, en las Tierras de la Peste del Oeste."},
    [5052] = {n="Esquirlas de sangre de Agamaggan", d="Llévale una esquirla de sangre a Quebrantadientes en el Campamento Taurajo en Los Baldíos.\nReúne más esquirlas de sangre si quieres que te bendiga con el poder de Agamaggan.", tgo={{"Cazador Erizapúas", "Buscaqua Erizapúas", "Tejespina Erizapúas", "Geomántica Erizapúas", "Defensor Crines de Acero", "Clamavientos Alabruja", "Sobrestante de Ventura y Cía.", "Vidente Crines de Acero"}}},
    [5054] = {n="Ursius de los Dentoesquirla", d="Ventisca Pezuña Umbría de Vista Eterna, en Cuna del Invierno, quiere que mates a Ursius.", tgo={{"Ursius"}}},
    [5058] = {n="El diario de la señora Dalson"},
    [5059] = {n="Encierro", d="Botín de: Esqueleto deambulante", tgo={{"Esqueleto deambulante"}}},
    [5060] = {n="Encierro", d="Botín de: Granjero Dalson", tgo={{"Granjero Dalson"}}},
    [5062] = {n="El fuego Sagrado", d="Recoge 10 pitas incendiarias y después pide consejo a Magatha Tótem Siniestro en el Alto de los Ancestros de Cima del Trueno.", objs={"Pita incendiaria"}},
    [5064] = {n="Espiando a los Tótem Siniestro", d="Localiza y reúne las 3 notas secretas que hay en Cumbre de la Nube Negra.", objs={"Cofre de documentos"}},
    [5082] = {n="La amenaza de los Nevada", d="Donova Cubilnevado de Cuna del Invierno quiere que mates 8 abrecaminos Nevada, 8 vigías del cubil Nevada y 8 totémicos Nevada.", tgo={{"Abrecaminos Nevada"}, {"Vigía del cubil Nevada"}, {"Totémico Nevada"}}},
    [5083] = {n="Aguardiente Nevada", d="Lleva el frasco vacío de aguardiente a Donova Cubilnevado de Cuna del Invierno."},
    [5084] = {n="Sucumbir a la corrupción", d="Busca una pista en el campamento fúrbolg Muertobosque en el norte de Frondavil."},
    [5085] = {n="Baba misteriosa", d="Informa sobre tus descubrimientos a Donova Cubilnevado."},
    [5086] = {n="Horrores tóxicos", d="Recoge 3 gotitas de horror tóxico para Donova Cubilnevado de Cuna del Invierno.", tgo={{"Horror tóxico"}}},
    [5087] = {n="Corredores Nevada", d="Encuentra a los corredores Nevada y detenlos antes de que entreguen su cargamento en Poblado Nevada.", tgo={{"Corredor Nevada"}}},
    [5096] = {n="Distracción Escarlata", d="Adéntrate en el campamento base de la Cruzada Escarlata entre el Campo de Piedramácula y el Llanto de Dalson y destruye su tienda de mando.\nColoca el estandarte de la Plaga en el campamento y vuelve con el sumo ejecutor Derrington en El Baluarte en las Tierras de la Peste del Oeste."},
    [5098] = {n="Todas las atalayas", d="Con la antorcha de aviso, marca las atalayas de Andorhal. Tendrás que estar en la entrada de la atalaya para poder marcarla.\nCuando estén marcadas las cuatro atalayas, devuelve la antorcha de aviso al sumo ejecutor Derrington en El Baluarte, en las Tierras de la Peste del Oeste.", tgo={{"Torre uno de Andorhal"}, {"Torre dos de Andorhal"}, {"Torre tres de Andorhal"}, {"Torre cuatro de Andorhal"}}},
    [5121] = {n="Gran Jefe Nevada", d="Donova Cubilnevado de Cuna del Invierno quiere que derrotes al Gran Jefe Nevada.", tgo={{"Gran Jefe Nevada"}}},
    [5122] = {n="El medallón de Fe", d="Usar/recoger: Caja fuerte de Malor", objs={"Caja fuerte de Malor"}},
    [5123] = {n="La pieza final", d="Lleva el diario mal escrito a Donova Cubilnevado de Cuna del Invierno."},
    [5125] = {n="La estimación de Aurius"},
    [5147] = {n="SE BUSCA: Arnak Tótem Siniestro", d="Mata a Arnak Tótem Siniestro y llévale una prueba de tu hazaña al vigiarrisco Cuerno Largo, que está en el Poblado Viento Libre.", tgo={{"Arnak Tótem Siniestro"}}},
    [5149] = {n="La muñeca de Pamela", d="Encuentra la muñeca de Pamela."},
    [5151] = {n="Hipercondensador", d="Acaba con la bestia y trae de regreso el hipercondensador y la llave de la jaula de pantera a Wizlo Rodabrillante.", tgo={{"Pantera iracunda"}}},
    [5152] = {n="Tía Marlene", d="Habla con Marlene. Está al sur de las Ruinas de Andorhal."},
    [5153] = {n="Una extraña historiadora", d="Lleva la alianza de Joseph a Cromi.", objs={"Monumento de Joseph Rutagrana"}},
    [5154] = {n="Las Crónicas de Villa Darrow", d="Lleva el libro Crónicas de Villa Darrow a Cromi a Andorhal.", objs={"Libro enmohecido"}},
    [5155] = {n="Las fuerzas de Jaedenar", d="Entra en Jaedenar y mata a 4 canes Jaedenar, 4 guardianes Jaedenar, 6 adeptos Jaedenar y 6 cultores Jaedenar antes de volver con Greta Pezuñamusgo a Frondavil.", tgo={{"Can Jaedenar"}, {"Guardián Jaedenar"}, {"Adepto Jaedenar"}, {"Cultor Jaedenar"}}},
    [5156] = {n="Verificación de la corrupción", d="Busca y destruye a 2 bestias entrópicas y 2 horrores entrópicos a la vez que exploras la Cañada Gran Cicatriz. Cuando hayas comprobado si los cráteres del lugar aún contienen agua vil corrupta, vuelve con Taronn Plumarroja a Frondavil.", tgo={{"Bestia entrópica"}, {"Horror entrópico"}}},
    [5157] = {n="Recolección de agua corrupta", d="Lleva la cantimplora vacía a la Poza de la Luna que hay en el centro de Jaedenar y llénala antes de volver con Greta Pezuñamusgo a Frondavil.", objs={"La Poza de la Luna corrupta de Jaedenar"}},
    [5158] = {n="En busca de ayuda espiritual", d="Lleva el agua de la Poza de la Luna corrupta a Islen Vidente del Agua a Los Baldíos."},
    [5159] = {n="El agua purificada regresa a Frondavil", d="Lleva el agua de la Poza de la Luna purificada a Greta Pezuñamusgo en Frondavil."},
    [5163] = {n="Yeti... ¿ya hemos llegado?", d="Coge el yeti mecánico de Umi y asusta con él a sus amigos:\nLegacki en Vista Eterna (Cuna del Invierno)\nRoxio en Gadgetzan (Tanaris)\nQuixxil en el Refugio de Marshal (Cráter de Un'Goro)\nCuando hayas terminado, devuelve el yeti mecánico a Umi.", tgo={{"Legacki"}, {"Roxio"}, {"Quixxil"}}},
    [5165] = {n="Sofocar las llamas de protección", d="Utiliza el agua de la Poza de la Luna purificada para apagar las llamas de los cuatro Blandones de Protección de la Guarida Sombría de Frondavil y vuelve con Greta Pezuñamusgo al Santuario Esmeralda.", objs={"Blandón del Dolor", "Blandón de la Maldad", "Blandón del Sufrimiento", "Blandón del Odio"}},
    [5211] = {n="Los defensores de Villa Darrow", d="Libera a 15 espíritus de Villa Darrow y vuelve con Carlin Rutagrana.", tgo={{"Espíritu de Villa Darrow"}}},
    [5212] = {n="La carne no miente", d="Consigue 20 muestras de carne apestadas de Stratholme y llévaselas a Betina Bigglezink. Tienes la sospecha de que podrás obtener ese tipo de carne de cualquier criatura de Stratholme.", tgo={{"Cadáver devastado", "Cadáver destrozado", "Necrófago de peste", "Cuervoso necrófago", "Necrófago desgarracarne", "Reptador de la cripta", "Bestia de la cripta", "Horror de retazos"}}},
    [5213] = {n="El agente activo", d="Viaja a Stratholme y busca los zigurats. Encuentra información sobre la Plaga y llévasela a Betina Bigglezink.", objs={"Información sobre la Plaga"}},
    [5214] = {n="El gran Ezra Grimm", d="Encuentra la Tienda de humo de Ezra Grimm en Stratholme y recupera una caja del tabaco de calidad de Grimm. Cuando lo hayas hecho, vuelve con Smokey LaRue.", tgo={{"Ezra Grimm"}}},
    [5228] = {n="Las calderas de la Plaga", d="Habla con la sacerdotisa de las Sombras Vandis en el Baluarte, en las Tierras de la Peste del Oeste."},
    [5229] = {n="Objetivo: Campo de Piedramácula", d="Ve al Campo de Piedramácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedramácula para obtener una muestra de los venenos utilizados en el interior de la caldera.", tgo={{"Señor de la caldera Garravil"}}},
    [5230] = {n="Regresa a El Baluarte", d="Lleva la Botella rellena del Campo de Piedramácula a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."},
    [5231] = {n="Objetivo: Llanto de Dalson", d="Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera.", tgo={{"Señor de la caldera Molevolus"}}},
    [5232] = {n="Regresa a El Baluarte", d="Lleva la botella del Llanto de Dalson llena a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."},
    [5233] = {n="Objetivo: El Tormento", d="Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera.", tgo={{"Señor de la caldera Razarch"}}},
    [5234] = {n="Regresa a El Baluarte", d="Lleva la Botella llena de El Tormento a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."},
    [5235] = {n="Objetivo: Gangrena de Gahrron", d="Ve a la Gangrena de Gahrron en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de la Gangrena de Gahrron para obtener una muestra de los venenos utilizados en el interior de la caldera.", tgo={{"Señor de la caldera Iralma"}}},
    [5236] = {n="Regresa a El Baluarte", d="Lleva la botella llena de la Gangrena de Gahrron a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."},
    [5238] = {n="¡Misión cumplida!", star={"Espada corta valerosa", {"PALADIN", "MAGE", "WARLOCK"}}},
    [5241] = {n="Tío Carlin", d="Encuentra a Carlin Rutagrana."},
    [5242] = {n="El golpe final", d="Mata a Moora y Salia y lleva la cabeza de Señor de las Sombras Fel'dan a Greta Pezuñamusgo a Frondavil.", tgo={{"Moora"}, {"Salia"}, {"Señor de las Sombras Fel'dan"}}},
    [5243] = {n="Las casas de lo sagrado", d="Viaja al norte, a Stratholme. Registra los cajones de provisiones que hay por toda la ciudad y recupera 5 de agua bendita de Stratholme. Vuelve junto a Leonid Barthalomew el Venerado cuando hayas reunido suficiente líquido bendecido.", objs={"Cajón de suministros", "Cajón de suministros de Stratholme"}},
    [5251] = {n="El archivista", d="Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata.", tgo={{"Archivista Galford"}, {}}, objs={"Archivo Escarlata"}},
    [5281] = {n="Espíritus inquietos", d="Encuentra a Egan. Solo sabes que fue visto por última vez en los alrededores de Stratholme."},
    [5282] = {n="Espíritus inquietos", d="Utiliza el libertador de Egan en los ciudadanos espectrales y fantasmas de Stratholme. Cuando las almas se liberen de sus recipientes fantasmales, vuelve a usarlo y lograrás liberarlos para siempre.\nLibera 15 almas y regresa a Egan.", tgo={{"Alma inquieta"}}},
    [5306] = {n="Piedra culebra de la cazadora de las Sombras", d="Viaja a la Cumbre de Roca Negra y mata a la cazadora de las Sombras Vosh'gajin. Recupera la piedra culebra de Vosh'gajin y vuelve con Kilram.", tgo={{"Cazador de las Sombras Vosh'gajin"}}},
    [5341] = {n="La fortuna de la familia Barov", d="Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras de Molino Tarren y Las escrituras de Costasur. Regresa con Alexi Barov cuando hayas terminado esta tarea.", objs={"Las escrituras de Rémol", "Las escrituras de Castel Darrow", "Las escrituras de Costasur", "Las escrituras de Molino Tarren"}},
    [5361] = {n="Árbol genealógico", d="Entrégale el informe de Vigiarisco Cuerno Largo a Nataka Cuerno Largo que se encuentra en el Campamento del Espíritu Errante de Desolace."},
    [5381] = {n="La Mano de Iruxos", d="Extrae la caja de demonio de la Fortaleza del Hacha de Trueno y llévasela a Taiga Crin Sabia a la Aldea Cazasombras junto con el pico de demonio.|n", tgo={{"Espíritu demoníaco"}}},
    [5382] = {n="Doctor Theolen Krastinov, el Carnicero", d="Busca al doctor Theolen Krastinov en el interior de Scholomance. Acaba con él y quema los restos de Eva Sarkhoff y los restos de Lucien Sarkhoff. Cuando hayas terminado tu tarea regresa con Eva Sarkhoff.", tgo={{"Doctor Theolen Krastinov"}, {}, {}}, objs={"Restos de Eva Sarkhoff", "Restos de Lucien Sarkhoff"}},
    [5386] = {n="La pesca del día", d="Habla con Jinar'Zillen, en la Aldea Cazasombras, y luego lleva 2 panzasangres a Nataka Cuerno Largo.", tgo={{"Jinar'Zillen"}}},
    [5441] = {n="Peones vagos", d="Utiliza la Cachiporra del supervisor con los peones vagos que estén durmiendo. Despierta a 5 peones y devuélvele la cachiporra al supervisor Thazz'ril en el Valle de los Retos.", tgo={{"Peón vago"}}},
    [5481] = {n="La tarea de Gordo", d="Recoge 3 hierbas luminiscentes y entrégaselas al boticario auxiliar Holland en el cementerio de Rémol.", objs={"Hierba luminiscente"}},
    [5482] = {n="Apocalíseas", d="Recoge 10 apocalíseas y entrégaselas al boticario auxiliar Holland.|n", objs={"Apocalíseas"}},
    [5501] = {n="Recolección de kodos", d="Lleva 10 huesos de kodo del Cementerio de Kodos a Bibbly F'utzhebilla a la Cabaña de Kormek.", objs={"Huesos de kodo"}},
    [5511] = {n="La llave de Scholomance"},
    [5514] = {n="Molde rima con... ¿oro?", d="Lleva los trozos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan."},
    [5518] = {n="El disfraz de ogro Gordok", d="Lleva 4 madejas de paño rúnico, 8 cueros bastos, 2 hilos rúnicos y tanino de ogro a Knot Llavededo. Actualmente está encadenado en el interior del ala Gordok de La Masacre.", objs={"Cofre de acero vil", "Cesta de tanino de ogro", "Alijo de Knot Thimblejack"}},
    [5525] = {n="¡Libera a Knot!", d="Botín de: Tosco Gordok, Señor de la magia Gordok, Capitán Gordok", tgo={{"Tosco Gordok", "Señor de la magia Gordok", "Capitán Gordok", "Brujo Gordok", "Atracador Gordok", "Guardia Fengus", "Guardia Slip'kik", "Capitán Kromcrush"}}},
    [5526] = {n="Fragmentos de gangrevid", d="Encuentra gangrevid en La Masacre y coge un fragmento. Es probable que solo puedas conseguirlo si derrotas a Alzzin el Formaferal. Usa el relicario de Pureza para guardar el fragmento y llévaselo a Rabine Saturna a Amparo de la Noche, en Claro de la Luna."},
    [5527] = {n="Un relicario de Pureza", d="Ve a Silithus a buscar un relicario de Pureza en las ruinas de la Aldea del Viento del Sur. Llévaselo a Rabine Saturna a Amparo de la Noche, en Claro de la Luna.", objs={"Relicario polvoriento"}},
    [5528] = {n="La cata de los Gordok"},
    [5529] = {n="Crías de dragón apestadas", d="Mata a 20 crías de dragón apestadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz.", tgo={{"Cría de dragón apestada"}}},
    [5534] = {n="El equipamiento \"perdido\" de Kim'jael", d="Encuentra una runa que los nagas guardan en las Ruinas de Eldarath y llévasela a Kim'jael en Azshara.", tgo={{"Sirena Látigo de Ira", "Mirmidón Látigo de Ira", "Maestra de batalla Látigo de Ira", "Encantadora Látigo de Ira"}}},
    [5535] = {n="Agitación espiritual", d="Mata a 6 aparecidas Altonato y 6 exanimatos Altonato antes de volver junto a Loh'atu en Azshara.", tgo={{"Aparecida Altonato"}, {"Exanimato Altonato"}}},
    [5536] = {n="Una tierra llena de odio", d="Mata 6 sátiros Haldarr, 2 tramposos Haldarr, 2 jurapenas Haldarr y vuelve junto a Loh'atu en la frontera de Vallefresno.", tgo={{"Sátiro Haldarr"}, {"Tramposo Haldarr"}, {"Jurapenas Haldarr"}}},
    [5542] = {n="Perros demoníacos", d="Mata 20 cachorros de can de peste, 5 canes de peste y 5 canes de peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Vadín.", tgo={{"Cachorro de can de peste"}, {"Can de peste"}, {"Can de peste demenciado"}}},
    [5543] = {n="Cielos sangrientos", d="Mata 30 murcipestes y vuelve con Tirion Vadín.", tgo={{"Murcipeste"}}},
    [5544] = {n="Gusanos carroñeros", d="Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Vadín cuando tengas 15 trozos de carne de gusano carroñero.", tgo={{"Larva carroñera", "Devorador carroñero"}}},
    [5561] = {n="El rodeo kodo", d="Lleva cinco kodos domados y el kombobulador kodo a Smeed Mezclatornillos, en el Campamento de los Mezclatornillos."},
    [5581] = {n="Los portales de la Legión", d="Cierra 6 portales en Aquelarre Mannoroc y regresa con Taiga Crin Sabia en Aldea Cazasombras.", tgo={{"Guardián del portal de demonios"}}},
    [5601] = {n="Pamela, mi hermana", d="Encuentra a Pamela Rutagrana en Villa Darrow."},
    [5648] = {n="Prendas de espiritualidad", d="Encuentra a la bruta Kor'ja y cura sus heridas usando la Sanación inferior (Rango 2). Después, concédele Palabra de Poder: Entereza y vuelve a Cerrotajo a hablar con Tai'jin.", tgo={{"Bruto Kor'ja"}}},
    [5649] = {n="Al servicio de la espiritualidad", d="Ve a Durotar y habla con Tai'jin."},
    [5650] = {n="Las prendas de la Oscuridad", d="Encuentra al Guardia de la Muerte Kel y cura sus heridas utilizando un hechizo de Sanación inferior (Rango 2). A continuación, concédele la Palabra de poder: entereza, y después ve a ver de nuevo al clérigo oscuro Beryl a Rémol.", tgo={{"Guardia de la Muerte Kel"}}},
    [5651] = {n="Al servicio de la Oscuridad", d="Habla con el clérigo oscuro Beryl en los Claros de Tirisfal."},
    [5652] = {n="Maleficio de Debilidad"},
    [5654] = {n="Maleficio de Debilidad", d="Habla con Ur'kyo en Orgrimmar."},
    [5658] = {n="Toque de debilidad"},
    [5679] = {n="Peste devoradora"},
    [5680] = {n="Guardia de las Sombras"},
    [5722] = {n="Buscando la cartera perdida", d="Inspecciona la Sima Ígnea en busca del cuerpo de Maur Tótem Siniestro y comprueba si porta algún objeto de interés."},
    [5723] = {n="Midiendo fuerzas con el enemigo", d="Localiza la Sima Ígnea en Orgrimmar y después mata a 8 troggs Furia Ardiente y 8 chamanes Furia Ardiente y después ve a ver de nuevo a Rahauro a Cima del Trueno.", tgo={{"Trogg Furia Ardiente"}, {"Chamán Furia Ardiente"}}},
    [5724] = {n="La vuelta de la cartera perdida", d="Lleva la cartera de Tótem Siniestro hasta Rahauro, en Cima del Trueno."},
    [5725] = {n="Poder destructivo", d="Llévale los libros Hechizos de las Sombras y Encantamientos desde el infierno a Varimathras, que está en Entrañas.", tgo={{"Cultor Hoja Abrasadora", "Brujo Hoja Abrasadora"}, {"Cultor Hoja Abrasadora", "Brujo Hoja Abrasadora"}}},
    [5726] = {n="Enemigos ocultos", d="Lleva una insignia de Teniente a Thrall a Orgrimmar.", tgo={{"Fanático Filo Ardiente", "Aprendiz Filo Ardiente"}}},
    [5727] = {n="Enemigos ocultos", d="Lleva la insignia de Teniente a Neeru Hojafuego. Averigua si cree que eres miembro de Filo Ardiente; luego ve a ver a Thrall a Orgrimmar.", tgo={{"Neeru Hojafuego"}}},
    [5728] = {n="Enemigos ocultos", d="Mata a Bazzalan y a Jergosh el Convocador y ve a ver a Thrall a Orgrimmar.", tgo={{"Bazzalan"}, {"Jergosh el Convocador"}}},
    [5729] = {n="Enemigos ocultos", d="Habla con Neeru Hojafuego en Orgrimmar."},
    [5730] = {n="Enemigos ocultos", d="Habla con Thrall en Orgrimmar y cuéntale lo que has averiguado."},
    [5741] = {n="El Cetro de Luz", d="Consigue el Cetro de Luz y llévaselo a Azore Aldamort a la torre de Ethel Rethor.|n", tgo={{"Vidente Filo Ardiente"}}},
    [5742] = {n="Redención", d="Escucha lo que Tirion Vadín tiene que contarte.", tgo={{"Tirión Vadín"}}},
    [5761] = {n="Matar a la bestia", d="Ve a la Sima Ígnea, mata a Taragaman el Hambriento y llévale su corazón a Neeru Hojafuego a Orgrimmar.", tgo={{"Taragaman el Hambriento"}}},
    [5762] = {n="Hemet Nesingwary", d="Lleva el cajón de Kravel a Hemet Nesingwary en Tuercespina."},
    [5763] = {n="La caza en Tuercespina", d="Lleva el cuerno de kodo de Roon a Hemet Nesingwary en Tuercespina."},
    [5781] = {n="De recuerdos olvidados", d="Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín.", tgo={{"Mercutio Comerroña"}}},
    [5802] = {n="La forja del Penacho en Llamas", d="Lleva el molde para llave esqueleto y 2 barras de torio a la cima de la Cresta del Penacho en Llamas en el Cráter de Un'Goro. Utiliza el molde para llave esqueleto en el lago de lava para forjar la llave esqueleto sin terminar.\nLlévale la llave esqueleto sin terminar al boticario Dithers a El Baluarte, en las Tierras de la Peste del Oeste.", objs={"Lago de lava de la Cresta del Penacho en Llamas"}},
    [5804] = {n="El escarabeo de Araj", d="Destruye a Araj el Invocador y lleva el Escarabeo de Araj al boticario Dithers en El Baluarte, en las Tierras de la Peste del Oeste.", objs={"Filacteria de Araj"}},
    [5843] = {n="¡Te damos la bienvenida!", d="Lleva el vale de regalo de Valle de los Retos a Magga."},
    [5844] = {n="¡Te damos la bienvenida!", d="Entrega el vale de regalo del Campamento Narache a Vorn Vidente del Cielo."},
    [5845] = {n="Del honor perdido", d="Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo de Honor perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín.", objs={"Símbolo de Honor perdido"}},
    [5846] = {n="Del amor y la familia", d="Viaja a la isla de Castel Darrow, en la región sur del centro de las Tierras de la Peste. Allí, busca pistas sobre el paradero del cuadro."},
    [5848] = {n="Del amor y la familia", d="Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'Del amor y la familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo.\nDevuelve la pintura a Tirion Vadín.", objs={"Cuadro a medias"}},
    [5863] = {n="La Base Machacaduna", d="Andi Lynn de Gadgetzan quiere que destruyas la Base Machacaduna y para conseguirlo tendrás que matar 10 toscos Machacadunas, 10 déspotas Machacadunas y a Gor'marok el Devastador.", tgo={{"Tosco Machacaduna"}, {"Déspota Machacaduna"}, {"Gor'marok el Devastador"}}},
    [5881] = {n="La sustitución", d="Maggran quiere que le entregues una carta a Grish Largo Camino en El Gran Elevador, en Los Baldíos."},
    [5901] = {n="Una Peste en la Cruzada", d="Utiliza el tarro de termitas vacío en los montones de termitas de las Tierras de la Peste del Este. Cuando hayas reunido 100 termitas de las Tierras de la Peste, vuelve con Mickey Levine, que está en El Baluarte, en Claros de Tirisfal.", objs={"Montículo grande de termitas"}},
    [5902] = {n="Una Peste en la Cruzada", d="Encuentra un lugar adecuado en el centro del Aserradero Crestanorte, en las Tierras de la Peste del Oeste, para colocar la barrica de termitas de las Tierras de la Peste."},
    [5922] = {n="Claro de la Luna", d="Utiliza el hechizo \"Teletransporte: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar."},
    [5926] = {n="Escucha la llamada", d="Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno."},
    [5927] = {n="Escucha la llamada", d="Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno."},
    [5928] = {n="Escucha la llamada", d="Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno."},
    [5930] = {n="Espíritu del gran oso", d="Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.", tgo={{"Espíritu del gran oso"}}},
    [5932] = {n="Vuelve a Cima del Trueno", d="Vuelve a Cima del Trueno para hablar con Turak Tótem de Runa en Alto de los Ancestros."},
    [6002] = {n="Cuerpo y corazón", d="Aplica el polvo de luna Cenarion a la piedra de lechúcico lunar que se encuentra entre Mulgore y Los Baldíos para provocar a Garraluna. Hecho esto, has de enfrentarte a Garraluna para obtener la fuerza física y de corazón que posee.\nHabla con Turak Tótem de Runa en Cima del Trueno cuando hayas acabado.", tgo={{"Espíritu de Garraluna"}}},
    [6022] = {n="Matar con un propósito", d="Viaja al Cruce de Corin al este y mata a los miembros de la Plaga que habitan allí. Recoge 7 piezas de putrefacción viva en 10 minutos. Utiliza el mortero y el majadero para convertir la putrefacción viva en putrefacción coagulada."},
    [6027] = {n="El Libro de los Ancestros", d="Consigue el Libro de los Ancestros y llévaselo a Azore Aldamort a la torre de Ethel Rethor.|n", tgo={{"Lord Kragaru"}}},
    [6029] = {n="El informe Vista Eterna", d="Entrega el informe de Vista Eterna al oficial Argenta Garush en El Baluarte, en las Tierras de la Peste del Oeste."},
    [6030] = {n="El duque Nicolas Zverenhoff", d="Entrega el libro, \"Estudios sobre la Comunicación con los Espíritus\", al duque Nicolas Zverenhoff en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."},
    [6042] = {n="Los pequeños problemas de la no-vida", d="Mata a 20 murcipestes tóxicos y 10 murcipestes monstruosos. Vuelve con Nathanos Clamañublo cuando hayas acabado.", tgo={{"Murcipeste nocivo"}, {"Murcipeste monstruoso"}}},
    [6061] = {n="Domesticar la bestia", d="Usa la fusta de doma para domar un zancudo de llanura adulto. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.", tgo={{"Zancudo de llanura adulto"}}},
    [6062] = {n="Domesticar la bestia", d="Usa la fusta de doma para domar un jabalí jaspeado temible. Practica un poco y devuélvele la fusta a Thotar en Cerrotajo.", tgo={{"Jabalí jaspeado feroz"}}},
    [6065] = {n="El camino del cazador", d="Habla con Yaw Crinafilada en el Poblado Pezuña de Sangre, en Mulgore."},
    [6066] = {n="El camino del cazador", d="Habla con Yaw Crinafilada en el Poblado Pezuña de Sangre, en Mulgore."},
    [6067] = {n="El camino del cazador", d="Habla con Yaw Crinafilada en el Poblado Pezuña de Sangre, en Mulgore."},
    [6068] = {n="El camino del cazador", d="Habla con Thotar en Cerrotajo."},
    [6069] = {n="El camino del cazador", d="Habla con Thotar en Cerrotajo."},
    [6070] = {n="El camino del cazador", d="Habla con Thotar en Cerrotajo, en Durotar."},
    [6081] = {n="Domesticar la bestia", d="Habla con Ormak Tirosiniestro en Orgrimmar."},
    [6082] = {n="Domesticar la bestia", d="Usa la fusta de doma para domar un escórpido acorazado. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo.", tgo={{"Escórpido acorazado"}}},
    [6083] = {n="Domesticar la bestia", d="Usa la fusta de doma para domar un reptador de espuma. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo.", tgo={{"Reptador de espuma"}}},
    [6087] = {n="Domesticar la bestia", d="Usa la fusta de doma para domar un acechador de pradera. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.", tgo={{"Acechador de pradera"}}},
    [6088] = {n="Domesticar la bestia", d="Usa la fusta de doma para domar un aguilón. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.", tgo={{"Aguilón"}}},
    [6089] = {n="Domesticar la bestia", d="Habla con Holt Tronacuerno en el Alto de los Cazadores, en Cima del Trueno."},
    [6126] = {n="Nuevas lecciones", d="Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrita Rafagaestelar."},
    [6127] = {n="La fuente del envenenamiento", d="Usa el muestrario de Cima Calígine vacío para recoger una muestra de agua de uno de los estanques de la cima.\nLuego llévale el muestrario de Cima Calígine lleno a Tonga Tótem de Runa a El Cruce, en Los Baldíos.", objs={"Dreadmist Peak Pool"}},
    [6128] = {n="Reunir los ingredientes del remedio", d="Llévale 5 raíces de tierra y 5 cuernos de kodo a Tonga Tótem de Runa en El Cruce para que pueda confeccionar un bálsamo curativo.", tgo={{"Retoño de azotador", "Furiavid"}, {"Kodo de los Baldíos Perdidos", "Kodo de Los Baldíos"}}},
    [6129] = {n="Curar la dolencia", d="Usa el bálsamo animal curativo sobre las 10 gacelas enfermas que se encuentran en la parte norte de Los Baldíos; así se curarán. Hemos recibido informes según los cuales se han avistado gacelas enfermas por la carretera que va de este a oeste en El Cruce.", tgo={{"Gacela enferma"}}},
    [6130] = {n="Poder contra el veneno", d="Vuelve a Cima del Trueno para hablar con Turak Tótem de Runa en Alto de los Ancestros."},
    [6134] = {n="La caza de ectoplasmas", d="Llévale 8 ectoplasmas y el cajón de imanes fantasmales a Hornizz Zumbala en Desolace.", tgo={{"Espectro centauro"}}},
    [6142] = {n="Almejas", d="Encuentra 10 piezas de carne de almeja blanda y llévaselas a Mai'Lahii a la Aldea Cazasombras.", tgo={{"Reptador Correarrecifes iracundo"}}},
    [6143] = {n="Otros pescados para freír", d="Mata a 7 mirmidones Filozante, 7 nagas Filozante y 5 hechiceras Filozante y luego ve a Cazasombras, en Desolace, a hablar con Drulzegar.", tgo={{"Mirmidón Filozante"}, {"Naga Filozante"}, {"Hechicera Filozante"}}},
    [6161] = {n="La búsqueda del tesoro de Masatormento", d="Encuentra la llave de plata de Masatormento. Encuentra la llave de oro de Masatormento. Encuentra y abre el cofre de Masatormento.", tgo={{"Reptador Golpeseco", "Tenazario Golpeseco"}, {"Naga Filozante", "Hechicera Filozante", "Guerrero Filozante", "Mirmidón Filozante", "Filón Filozante", "Cazamareas Filozante", "Oráculo Filozante", "Bruja de mar Filozante"}}},
    [6162] = {n="La última batalla de un esposo", d="Mata al señor supremo Ror y lleva su garra a Dreka'Sur al Puesto del Veneno de Frondavil.", tgo={{"Señor supremo Ror"}}},
    [6164] = {n="Libro de entradas de Augustus", d="Lleva el libro de entradas de Augustus a Augustus el Agraciado en Valle del Terror.", objs={"Libro de entradas de Augustus"}},
    [6282] = {n="La amenaza de las arpías", d="Maggran Vinculador Terrestre, en el Refugio Roca del Sol, quiere que mates 7 arpías Furia Sangrienta, 7 emboscadoras Furia Sangrienta, 7 destripadoras Furia Sangrienta y 7 malaplumas Furia Sangrienta.", tgo={{"Arpía Furia Sangrienta"}, {"Emboscadora Furia Sangrienta"}, {"Destripadora Furia Sangrienta"}, {"Malapluma Furia Sangrienta"}}},
    [6283] = {n="El linaje Furia Sangrienta", d="Maggran, en el Refugio Roca del Sol, quiere que mates a la desgarradora Furia Sangrienta y le lleves sus restos como prueba de tu hazaña.", tgo={{"Desgarradora Furia Sangrienta"}}},
    [6284] = {n="Aracnofobia", d="Mata a Besseleth y lleva el colmillo de Besseleth a Maggran en el Refugio Roca del Sol.", tgo={{"Besseleth"}}},
    [6301] = {n="El ciclo del renacimiento", d="Tammra Campo de Viento, en el Refugio Roca del Sol, quiere que le consigas 10 semillas de Gaia.", objs={"Semilla de Gaia"}},
    [6381] = {n="Nueva vida", d="Planta 10 semillas de Gaia en los Túmulos y lleva las semillas de Gaia encantadas restantes a Tammra en el Refugio Roca del Sol.", objs={"Túmulo de Gaia"}},
    [6382] = {n="La Caza de Vallefresno", d="Habla con Senani Corazón Atronador en Puesto del Hachazo, en Vallefresno."},
    [6383] = {n="La Caza de Vallefresno"},
    [6390] = {n="Una Peste en la Cruzada", d="Libera las termitas de las Tierras de la Peste en el Aserradero Crestanorte y luego vuelve con la barrica de termitas de las Tierras de la Peste a Mickey Levine en El Baluarte en los Claros de Tirisfal."},
    [6393] = {n="Guerra elemental", d="Lleva 10 incendritas a Tsunaman en el Refugio Roca del Sol.", tgo={{"Espíritu flameante huido", "Devastador ardiente", "Destructor ardiente"}}},
    [6394] = {n="Pico de Thazz'ril", d="Lleva el pico de Thazz'ril al supervisor Thazz'ril.", objs={"Pico de Thazz'ril"}},
    [6395] = {n="El último deseo de Marla", d="Lleva los restos de Samuel Fipps a la tumba de Marla y luego vuelve con la novicia Elreth.", objs={"Tumba de Marla"}},
    [6421] = {n="Barranco del Alud", d="Explora las profundidades de la cueva del Barranco del Alud y lleva 10 cristales de resonita al Refugio Roca del Sol para que Mor'rogal las estudie.", objs={"Cristal de resonita"}},
    [6441] = {n="Los cuernos de sátiro", d="Reúne 16 cuernos de sátiro para Pixie en el Puesto del Hachazo.", tgo={{"Pícaro Xavian", "Desertor Xavian", "Jurapenas Xavian", "Clamainferno Xavian", "Sátiro Putredor", "Pícaro Putredor", "Jurapenas Putredor", "Acechasombras Putredor"}}},
    [6442] = {n="Nagas en la Ensenada de Zoram", d="Llévale 20 cabezas de Colafuria a Marukai en La Ensenada de Zoram.", tgo={{"Myrmidón Colafuria", "Filón Colafuria", "Jinete de olas Colafuria", "Bruja de mar Colafuria", "Hechicera Colafuria", "Sacerdotisa Colafuria"}}},
    [6461] = {n="Chupasangres", d="Xen'zilla, en Malaka'Jin, necesita que mates a 10 trepadores Musgondo y a 7 escupevenenos Musgondo.", tgo={{"Trepador Musgondo"}, {"Escupetósigo Musgondo"}}},
    [6462] = {n="El talismán trol", d="Llévale 8 talismanes trols a Mitsuwa en la Avanzada de Zoram'gar.", objs={"Cofre trol"}},
    [6481] = {n="El despertar del terráneo", d="Abre el barril de resonita con el cristal de resonita encantado y, a continuación, mata a Goggeroc. Vuelve a ver a Mor'rogal para contarle lo ocurrido y entregarle el cristal de resonita encantado.", tgo={{"Goggeroc"}}},
    [6482] = {n="Liberar a Ruul", d="Escolta a Ruul y después habla con Yama Pezuña Nevada en el Puesto del Hachazo."},
    [6503] = {n="Avanzada de Vallefresno", d="Mata a 9 avanzadas de Vallefresno y regresa con Kuray'bin en Puesto del Hachazo.", tgo={{"Avanzada de Vallefresno"}}},
    [6504] = {n="Las páginas perdidas", d="Encuentra las 12 páginas que faltan del manual de instrucciones de trituradora y vuelve a componer con ellas los 3 primeros capítulos. Devuélvele las páginas a Gurda Cicafuria cerca del Puesto del Hachazo.|n"},
    [6521] = {n="Una alianza impía", d="Lleva la cabeza del embajador Malcin a Varimathras en Entrañas.", tgo={{"Embajador Malcin"}}},
    [6522] = {n="Una alianza impía", d="Lleva el pergamino pequeño a Varimathras en Entrañas."},
    [6541] = {n="Preséntate ante Kadrak", d="Preséntate ante Kadrak en la torre de vigilancia en Los Baldíos del Norte."},
    [6543] = {n="Los informes Grito de Guerra", d="Abre el fardo de informes. Lleva los informes Grito de Guerra al explorador Grito de Guerra, al corredor Grito de Guerra y al escolta Grito de Guerra. Preséntate ante Kadrak en la torre de vigilancia norte en los Baldíos con la información que te hayan dado."},
    [6544] = {n="El asalto de Torek", d="Escolta a Torek en su ataque sobre la Avanzada Ala de Plata contra Duriel Fuegolunar e informa después a Ertog Colmillorrabioso en el Puesto del Hachazo."},
    [6545] = {n="Novedades de corredor Grito de Guerra"},
    [6546] = {n="Novedades de escolta Grito de Guerra"},
    [6547] = {n="Novedades de explorador Grito de Guerra"},
    [6561] = {n="La vileza de Brazanegra", d="Llévale la cabeza del señor crepuscular Kelris a Bashana Tótem de Runa en Cima del Trueno.", tgo={{"Señor Crepuscular Kelris"}}},
    [6562] = {n="Problemas en las profundidades", d="Habla con Je'neu Sancrea en Vallefresno."},
    [6563] = {n="La esencia de Aku'Mai", d="Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno.", objs={"Zafiro de Aku'Mai"}},
    [6564] = {n="Lealtad a los dioses antiguos", d="Llévale la nota mojada a Je'neu Sancrea en Vallefresno."},
    [6565] = {n="Lealtad a los dioses antiguos", d="Mata a Lorgus Jett en las Cavernas de Brazanegra y vuelve con Je'neu Sancrea en Vallefresno.", tgo={{"Lorgus Jett"}}},
    [6621] = {n="El rey de los Maderiza", d="Coloca el estandarte de Karang en el montículo del tótem de los Maderiza. No permitas que los fúrbolgs destruyan el estandarte. Derrota al jefe Murgut y lleva el tótem de Murgut a Karang Amakkar en Zoram'gar.", tgo={{"Jefe Murgut"}}},
    [6626] = {n="Un anfitrión del mal", d="Mata a 8 guardias de batalla de Rajacieno y 8 tejespinas Rajacieno y 8 cultores Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno.", tgo={{"Guardia de batalla de Rajacieno"}, {"Tejespina de Rajacieno"}, {"Cultor Caramuerte"}}},
    [6627] = {n="Prueba de conocimiento", d="Responde la pregunta de Braug Espíritu Tenue con acierto y después habla con él de nuevo. Se quedará en Sierra Espolón hasta que estés listo."},
    [6641] = {n="Vorsha la Azotadora", d="Mantén a Muglash a salvo mientras viaja hacia el blandón. Apaga el blandón para ayudarlo y luego lucha contra los nagas para protegerlo.\nSi tienes éxito, regresa a Avanzada de Zoram'gar e informa al corredor Grito de Guerra sobre la muerte de Vorsha la Azotadora."},
    [6681] = {n="Mansión Ravenholdt", d="Lleva el Sello de Ravenholdt a Fahrad, que está en la Mansión Ravenholdt, en las colinas de Trabalomas.\nTendrás que poner a prueba tu ingenio por el camino. Ándate con ojo.", tgo={{"Ravenholdt"}}},
    [6701] = {n="Emblemas de la Hermandad", d="Botín de: Asesino de la Hermandad, Conjurador de la Hermandad, Asaltante de caminos de la Hermandad", tgo={{"Asesino de la Hermandad", "Conjurador de la Hermandad", "Asaltante de caminos de la Hermandad", "Bandolero de la Hermandad", "Mercenario de la Hermandad", "Acechacaminos de la Hermandad", "Merodeador de la Hermandad", "Espía de la Hermandad"}}},
    [6844] = {n="Umber, el archivista", d="Lleva el objeto silítido taraceado a Umber, el archivista del Círculo Cenarion, en la aldea de Amparo de la Noche, en el Claro de la Luna."},
    [6845] = {n="Desvelar los secretos del pasado", d="Habla con Rabine Saturna en el poblado Amparo de la Noche, en Claro de la Luna."},
    [6921] = {n="Entre ruinas", d="Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.", objs={"Piedra de las profundidades"}},
    [6922] = {n="Barón Aquanis", d="Llévale el extraño globo de agua a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno."},
    [6981] = {n="El fragmento resplandeciente", d="Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento resplandeciente.\nEntrega el fragmento como se te indique.", tgo={{"Petardol"}}},
    [7003] = {n="Gigantes reducidos", d="Utiliza el Ultra-reductor de Zorbin para encoger a cualquier gigante que encuentres en Feralas a un tamaño más manejable. Lleva 15 residuos de miniaturización encontrados en las versiones encogidas de los gigantes a Zorbin Hipnoviento, al embarcadero de La Costa Olvidada de Feralas.", tgo={{"Caminatierras", "Gigante del risco", "Zancaorillas", "Zancaprofunda", "Asaltaolas", "Zancacostas machacado", "Caminatierras machacado", "Asaltaolas machacado"}}},
    [7028] = {n="Los males de Maraudon", d="Recoge 25 tallas de cristal terádrico para Willow en Desolace.", tgo={{"Centauro maldito", "Sátiro Putridus", "Tramposo Putridus", "Acechasombras Putridus", "Dríade celebriana", "Hermana de Celebrian", "Princesa Theradras", "Derrumblo"}}},
    [7029] = {n="La corrupción de Lenguavil", d="Llena el vial cerúleo cubierto en el estanque naranja de Maraudon.\nAplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico.\nCura 8 plantas eliminando su sucesor tóxico e informa a Vark Marca de Guerra en la Aldea Cazasombras.", tgo={{"Sucesor tóxico"}, {}}, objs={"Estanque Naranja de Maraudon"}},
    [7044] = {n="Leyendas de Maraudon", d="Recupera las 2 partes del cetro de Celebras: la vara y el diamante de Celebras.\nEncuentra el modo de hablar con Celebras.", tgo={{"Lord Lenguavil"}, {"Noxxion", "Engendro de Noxxion"}}},
    [7046] = {n="El cetro de Celebras", d="Ayuda a Celebras el Redimido mientras reconstruye el cetro de Celebras.\nHabla con él después del ritual.", objs={"Incantation of Celebras"}},
    [7064] = {n="Corrupción de la tierra y de la semilla", d="Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace.", tgo={{"Princesa Theradras"}}},
    [7066] = {n="La semilla de vida", d="Busca a Remulos en Claro de la Luna y dale la semilla de vida."},
    [7067] = {n="Las instrucciones del Paria", d="Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace."},
    [7068] = {n="Trozos Oscuros", d="Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar.", tgo={{"Estruendor Fragmento Oscuro", "Quebrantador Fragmento Oscuro", "Tronador Fragmento Oscuro"}}},
    [7201] = {n="El último elemento", d="Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los gólems y a los creadores de gólems. Recuerdas que Vivian Lagrave también murmuró entre dientes algo sobre los elementales.", tgo={{"Gólem de guerra fundido", "Gólem Furiatracador", "Constructo Belisario", "Guardia de fuego", "Guardia de fuego llameante", "Destructor guardia de fuego", "Panzor el Invencible", "Lord Incendius"}}},
    [7441] = {n="Pusillín y el ancestro Azj'Tordin", d="Viaja a La Masacre y encuentra al diablillo Pusillín. Convence a Pusillín de que te dé el libro de Conjuros de Azj'Tordin, por cualquier medio.\nSi consigues hacerte con el libro de Conjuros, vuelve al Pabellón de Lariss de Feralas y busca a Azj'Tordin.", tgo={{"Pusillín"}}},
    [7461] = {n="Locura interior", d="Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará.\nEntra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum.\nSi consigues completar esta misión, ve al patio a buscar a la ancestro Shen'dralar.", tgo={{"Immol'thar"}, {"Príncipe Tortheldrin"}}},
    [7463] = {n="El refresco arcano", d="Viaja al Barrio Alabeo de La Masacre y mata al elemental de agua, Hidromilecio. Lleva la esencia de Hidromilecio al Tradicionalista Lydros que está en El Athenaeum.", tgo={{"Hidromilecio"}}},
    [7481] = {n="Leyendas élficas", d="Busca a Telmius Buscasueños en La Masacre. Vuelve al Campamento Mojache e informa al Sabio Korolusk de cualquier cosa que encuentres.", objs={"Restos esqueléticos de Telmius Buscasueños"}},
    [7489] = {n="La membrana de Lethtendris", d="Lleva la Membrana de Lethtendris a Talo Pezuñahendida al Campamento Mojache de Feralas.", tgo={{"Lethtendris"}}},
    [7492] = {n="Campamento Mojache", d="Ve al Campamento Mojache de Feralas y habla con Talo Pezuñahendida."},
    [7498] = {n="Garona: Un Estudio sobre el Sigilo y la Traición", d="Devuelve el libro a sus legítimos dueños."},
    [7499] = {n="Códice de Defensa", d="Devuelve el libro a sus legítimos dueños."},
    [7500] = {n="El libro de cocina del Arcanista", d="Devuelve el libro a sus legítimos dueños."},
    [7501] = {n="La Luz y cómo alterarla", d="Devuelve el libro a sus legítimos dueños."},
    [7502] = {n="Sombras acechadoras", d="Devuelve el libro a sus legítimos dueños."},
    [7503] = {n="La mejor raza de cazadores", d="Devuelve el libro a sus legítimos dueños."},
    [7504] = {n="Sagrada Bologna: lo que la Luz nunca te dirá", d="Devuelve el libro a sus legítimos dueños."},
    [7505] = {n="El choque de Escarcha y tú", d="Devuelve el libro a sus legítimos dueños."},
    [7506] = {n="El Sueño Esmeralda", d="Devuelve el libro a sus legítimos dueños."},
    [7601] = {n="La orden de Niby", d="Habla con Diblis en Frondavil."},
    [7602] = {n="Esencia de energía vil pura", d="Diblis de Frondavil te ha pedido que le lleves 3 esencias viles impecables que provengan de 3 lugares distintos.\nLos sátiros Legashi de Azshara tienen la esencia vil impecable de su región. Los Legionarios Jaedenar de Jaedenar tienen la esencia vil impecable de su región. Los guardias viles de Las Tierras Devastadas tienen la esencia vil impecable de su región.\nReúne las esencias viles impecables y vuelve con Diblis a Frondavil.", tgo={{"Sátiro Legashi", "Pícaro Legashi", "Clamainferno Legashi", "Legashi Soulstealer", "Legashi Hellraiser", "Legashi Blackguard"}, {"Legionario Jaedenar"}, {"Avizor guardia vil"}}},
    [7603] = {n="El núcleo infernal de Kroshius", d="Busca los restos de Kroshius en la Cañada Gran Cicatriz de Frondavil. Cuando localices sus restos, utiliza el fuego vil cerca de ellos y espera el regreso de Kroshius. Cuando el infernal se haya despertado, acaba con él y extrae de su cuerpo el núcleo infernal de Kroshius.\nLleva el núcleo infernal de Kroshius a Niby el Todopoderoso a Frondavil.", tgo={{"Kroshius"}, {"Kroshius"}}},
    [7701] = {n="SE BUSCA: Sobrestante Maltorius", d="El traidor Hierro Negro llamado sobrestante Maltorius está en La Fosa de la Escoria de La Caldera, en La Garganta de Fuego.\nMátalo y lleva su cabeza al capitán de vigía Lolo Zancalarga a La Garganta de Fuego para recibir tu recompensa.", tgo={{"Sobrestante Maltorius"}}},
    [7721] = {n="Combustible para el Ultra-reductor", d="Reúne 10 núcleos de elemental de agua de los elementales marinos y de los rocíos marinos que hay en La Costa Olvidada de Feralas, y llévaselos a Zorbin Hipnoviento, que está cerca del embarcadero.", tgo={{"Elemental de mar", "Rocío del mar"}}},
    [7722] = {n="¿Qué pasa con el flujo?", d="Busca los diseños secretos: flujo ígneo robados por el sobrestante Maltorius en La Fosa de la Escoria de La Caldera. Llévaselos al herrero maestro Burninate a La Garganta de Fuego.", objs={"Diseños secretos: flujo ígneo"}},
    [7723] = {n="¡Malditos dedos gordos!", d="Hansel Manospesadas quiere que mates 20 gólems de guerra pesados.\nSuelen estar cerca de La Caldera en La Garganta de Fuego. Después ve a ver a Hansel a La Garganta de Fuego.", tgo={{"Gólem de guerra pesado"}}},
    [7724] = {n="Amenaza abrasadora", d="Hansel Manospesadas quiere que mates 20 arañas de lava superiores en La Garganta de Fuego. Las encontrarás en las mesetas y los estanques de lava de La Garganta de Fuego.\nCuando hayas matado suficientes arañas de lava superiores ve a ver a Hansel Manospesadas a La Garganta de Fuego.", tgo={{"Araña de lava abrasadora"}}},
    [7727] = {n="¿Incendosaurio? Loqueseasaurio más bien", d="Hansel Manospesadas quiere que mates 20 incendosaurios.\nSuelen estar en los estanques de lava de La Fosa de la Escoria. La Fosa de la Escoria está en La Caldera de La Garganta de Fuego.\nCuando hayas matado suficientes incendosaurios ve a ver a Hansel Manospesadas a La Garganta de Fuego.", tgo={{"Incendosaurio"}}},
    [7728] = {n="OBJETOS ROBADOS: Tobera y catalejo", d="Encuentra la tobera y el catalejo y llévaselos al capataz Scrange a La Garganta de Fuego.\nLo único que sabes es que fueron robados por enanos Hierro Negro. La tobera es una herramienta de herrero y el catalejo es un instrumento muy valioso para los oteadores.", tgo={{"Vapoherrero Hierro Negro"}, {"Oteador Hierro Negro"}}},
    [7729] = {n="OPORTUNIDAD LABORAL: Acabar con la competencia", d="Mata a 15 Capataces y 15 esclavistas Hierro Negro y ve a ver al capataz Scrange a La Garganta de Fuego.", tgo={{"Capataz Hierro Negro"}, {"Esclavista Hierro Negro"}}},
    [7730] = {n="Infestación de Zukk'ash", d="Lleva 20 caparazones Zukk'ash a Hadoken Zanco Veloz al Campamento Mojache en Feralas.", tgo={{"Aguijonero Zukk'ash", "Avispa Zukk'ash", "Trabajador Zukk'ash", "Tunelador Zukk'ash", "Latigador con aguijón"}}},
    [7731] = {n="Latigador con aguijón", d="Derrota al latigador con aguijón en Las Galerías Retorcidas y lleva sus glándulas a Hadoken Zanco Veloz al Campamento Mojache en Feralas.", tgo={{"Latigador con aguijón"}}},
    [7732] = {n="El informe Zukk'ash", d="Entrega a Zilzibin Tambor Sabio el informe del campamento Mojache Zukk'ash. Reside en La Calle Mayor de Orgrimmar."},
    [7734] = {n="Calidad mejorada", d="Lleva 10 pellejos de yeti Cicatriz de Rabia a Jangdor Zanco Veloz al Campamento Mojache de Feralas.", tgo={{"Yeti Cicatriz de Rabia", "Ancestro Cicatriz de Rabia", "Cicatriz de Rabia feroz", "Cicatriz Feral acechante"}}},
    [7738] = {n="Pellejo de yeti perfecto", d="Lleva los pellejos de yeti perfecto a Jangdor Zanco Veloz al Campamento Mojache de Feralas."},
    [7761] = {n="Orden de Puño Negro", d="¡Será estúpido ese orco! Al parecer, tienes que encontrar la enseña y ganar la marca de Drakkisath para poder acceder al orbe de orden.\nSegún la carta, el general Drakkisath guarda la enseña. Quizás deberías investigarlo."},
    [7815] = {n="¡Quijafortes, colega!", d="Katoom el Pescador, del Poblado Sañadiente en las Tierras del Interior, quiere que mates 15 tortugas quijaforte marinas. Ve a verlo cuando hayas terminado.", tgo={{"Quijaforte marino"}}},
    [7816] = {n="¡Gammerita, colega!", d="Katoom el Pescador, del Poblado Sañadiente en las Tierras del Interior, quiere que mates a Gammerita y que le saques el cebo del estómago.\nDijo que Gammerita está en la costa con las otras tortugas.", tgo={{"Gammerita"}}},
    [7828] = {n="Acechar a los acechadores", d="El montero Markhor, del Poblado Sañadiente en las Tierras del Interior, quiere que mates 15 acechadores melenargenta y 15 aulladores melenargenta. Vuelve a verlo cuando hayas terminado.\nMarkhor dijo que los lobos se ocultan entre la maleza en las Tierras del Interior.", tgo={{"Acechador melenargenta"}, {"Aullador melenargenta"}}},
    [7829] = {n="Cazar a los salvajes", d="El montero Markhor, del Poblado Sañadiente en las Tierras del Interior, quiere que mates 20 lechubestias salvajes. Vuelve a verlo cuando hayas terminado.\nMarkhor dijo que las lechubestias salvajes se ocultan entre la maleza en las Tierras del Interior.", tgo={{"Lechubestia salvaje"}}},
    [7830] = {n="Vengar a los Caídos", d="El montero Markhor, del Poblado Sañadiente en las Tierras del Interior, quiere que mates a un Señor del Cielo y le lleves la péndola.\nDijo que son una raza poco común que se extiende por toda la región.", tgo={{"Señor del Cielo Picovaja"}}},
    [7839] = {n="Los vándalos de Vilrama", d="El herrero Esco de Poblado Sañadiente, en las Tierras del Interior, quiere que encuentres y le lleves sus herramientas perdidas.\nDijo que las herramientas pueden estar en uno de los templos Vilrama en la zona noreste de las Tierras del Interior. Mira también en Roca Oculta.", objs={"Herramientas perdidas de Esco"}},
    [7840] = {n="Lard perdió su almuerzo", d="Lard, del Poblado Sañadiente en las Tierras del Interior, quiere que vayas a buscar su almuerzo. Llévaselo cuando lo encuentres.\nDijo que se lo dejó en la isla del norte. Ten cuidado con los trols Vilrama.", tgo={{"Secuestrador Vilrama"}}},
    [7845] = {n="El secuestro del anciano Colmillopartido", d="Primigenia Colmillopartido del Poblado Sañadiente, en las Tierras del Interior, quiere que rescates a su compañero, el anciano Colmillopartido, que está en Jintha'alor.\nTe han dicho que lo tienen prisionero en la cima de Jintha'alor, la capital vilrama al sur de las Tierras del Interior."},
    [7846] = {n="¡Recupera la llave!", d="El anciano Colmillopartido de Jintha'alor quiere que mates a Hitah'ya la Guardiana para quitarle la llave de sus grilletes. Vuelve a verlo cuando hayas conseguido la llave.", tgo={{"Hitah'ya la Guardiana"}}},
    [7847] = {n="Regresa junto a Primigenia Colmillopartido", d="El anciano Colmillopartido de Jintha'alor quiere que informes de su rescate a Primigenia Colmillopartido en el Poblado Sañadiente."},
    [7848] = {n="Armonización con el Núcleo", d="Acércate al portal de entrada del Núcleo de Magma en las Profundidades de Roca Negra y recoge un trozo del Núcleo. Llévaselo a Lothos Levantagrietas a la Montaña Roca Negra.", objs={"Trozo del Núcleo"}},
    [7849] = {n="Una separación angustiosa", d="El montero Markhor de Poblado Sañadiente, en las Tierras del Interior, quiere que le lleves los restos de su hermano gemelo. Llévale la calavera y los huesos de Malkhor.\nDijo que los Vilrama habían arrojado los restos de su hermano a los mocos y los lobos. También dijo que hay una fosa llena de mocos en Jintha'alor, además de una guarida de lobos, ambas cerca de la parte alta del templo.", objs={"Montón de cráneos", "Montón de huesos"}},
    [7850] = {n="Vasijas oscuras", d="Primigenia Colmillopartido del Poblado Sañadiente, en las Tierras del Interior, quiere que recojas 10 vasijas de sangre corrupta en Jintha'alor. Vuelve a verla cuando hayas terminado la tarea.", objs={"Vasija de sangre corrupta"}},
    [7861] = {n="Se busca: sacerdotisa vil Hexx y sus esbirros", d="Te han ordenado que mates a la sacerdotisa vil Hexx y a 20 guardias Aman'zasi Vilrama. Ve a ver a Primigenia Colmillopartido al Poblado Sañadiente en las Tierras del Interior cuando hayas terminado.\nEncontrarás a la sacerdotisa vil Hexx y a los guardias en la cima de Jintha'alor, en las Tierras del Interior.", tgo={{"Sacerdotisa vil Hexx"}, {"Guardia Aman'zasi Vilrama"}}},
    [7862] = {n="Oferta de empleo: capitán de la guardia de Poblado Sañadiente", d="Se te ha asignado la tarea de aniquilar a 20 rabiosos Vilrama, 20 cazadores de las Sombras Vilrama, 20 bebesangres Vilrama y 20 comealmas Vilrama.\nCuando hayas terminado, ve a ver a Primigenia Colmillopartido al Poblado Sañadiente, en las Tierras del Interior.", tgo={{"Rabioso Vilrama"}, {"Cazador de las Sombras Vilrama"}, {"Bebesangre Vilrama"}, {"Comealmas Vilrama"}}, star={"Runa del capitán de la guardia", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}},
    [7877] = {n="El tesoro de los Shen'dralar", d="Vuelve a El Athenaeum y encuentra el tesoro de los Shen'dralar. ¡Reclama tu recompensa!"},
    [8151] = {n="El talismán del cazador", d="Habla con Ogtinc en Azshara."},
    [8153] = {n="Cornamenta de trotador", d="Llévale una cornamenta perfecta de trotador a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tgo={{"Trotador Pezuñamusgo"}}},
    [8231] = {n="Los vándalos marinos", d="Llévale 6 escamas de descarnador marino a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tgo={{"Vándalo marino joven", "Vándalo marino", "Gran vándalo marino"}}},
    [8232] = {n="El draco verde", d="Llévale el diente de Morphaz a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tgo={{"Morphaz"}}, star={"Ojo de demosaurio", {"HUNTER"}}},
    [8233] = {n="Un pedido sencillo", d="Habla con Lord Jorach Ravenholdt en la Mansión Ravenholdt."},
    [8234] = {n="Bolsa azur sellada", d="Recupera la bolsa azur sellada del chamán Fauces de Madera en Azshara. Llévale entonces la bolsa al archimago Xylem, que también se encuentra en Azshara.", tgo={{"Chamán Fauces de Madera", "Blackmaw Shaman"}}},
    [8235] = {n="Los trozos codificados", d="Llévale 10 fragmentos codificados al archimago Xylem en Azshara.", tgo={{"Moco del bosque"}}},
    [8236] = {n="La llave azur", d="Devuélvele la llave azur a Lord Jorach Ravenholdt.", tgo={{"Morphaz"}}, star={"Mantón de Murciumbrío", {"ROGUE"}}},
    [8250] = {n="Pura magia", d="Busca a Sanath Lim-yo y obtén permiso para ver al archimago Xylem."},
    [8251] = {n="El polvo mágico", d="Llévale 10 puñados de polvo relumbrante al archimago Xylem.", tgo={{"Perito elfo de sangre", "Reivindicador elfo de sangre", "Defensor elfo de sangre", "Blood Elf Arcanist", "Evin Schmidtt", "Lumina Vientocantor"}}},
    [8252] = {n="El coral de las sirenas", d="Reúne 6 corales encantados y llévaselos al archimago Xylem.", tgo={{"Sirena Látigo de Ira"}}},
    [8253] = {n="Destruye a Morphaz", d="Recupera el fragmento arcano de Morphaz y llévaselo al archimago Xylem.", tgo={{"Morphaz"}}, star={"Rubí de fuego", {"MAGE"}}},
    [8254] = {n="Ayuda a Cenarion", d="Busca a Ogtinc en Azshara."},
    [8255] = {n="Los trotadores Pezuñamusgo", d="Consigue 4 glándulas de trotadores sanos y llévaselas a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tgo={{"Trotador Pezuñamusgo"}}},
    [8256] = {n="El icor de los no-muertos", d="Consigue un icor de no-muerto para Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tgo={{"Zombi Zanzil", "Cazador Zanzil", "Despellejador esquelético", "Hechicero esquelético", "Terror esquelético", "Verdugo esquelético", "Señor de la guerra esquelético", "Acólito esquelético"}}},
    [8257] = {n="La sangre de Morphaz", d="Mata a Morphaz en El Templo Sumergido de Atal'Hakkar y lleva su sangre a Greta Pezuñamusgo en Frondavil. Encontrarás la entrada al Templo Sumergido en el Pantano de las Penas.", tgo={{"Morphaz"}}, star={"Cuentas de rezo benditas", {"PRIEST"}}},
    [8276] = {n="La reconquista de Silithus", d="Habla con Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus."},
    [8277] = {n="Veneno mortal del desierto", d="Beetix Castañeta en el Fuerte Cenarion, en Silithus, quiere que consigas 8 aguijones de escórpido Latipiedra y 8 colmillos de arácnidos de arena. Vuelve a verla cuando hayas cumplido tu misión.", tgo={{"Escórpido Latipiedra"}, {"Arácnido de arena"}}},
    [8278] = {n="La última esperanza de Noggle", d="Beetix Castañeta en el Fuerte Cenarion, en Silithus quiere que consigas 3 aguijoneros de tenazario Latipiedra, 3 aguijoneros de despellejador Latipiedra y 3 colmillos de acecharrocas.", tgo={{"Despellejador Latipiedra"}, {"Tenazario Latipiedra"}, {"Acecharrocas"}}},
    [8280] = {n="Asegurar las rutas de suministros", d="Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus, quiere que mates a 15 golpeadores deslizantes.", tgo={{"Asediador deslizante"}}},
    [8281] = {n="Intensificar la seguridad", d="Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus, quiere que mates a 20 trituradores deslizantes.", tgo={{"Triturador deslizante"}}},
    [8284] = {n="El misterio Crepuscular", d="La Geóloga Trotuina en el Fuerte Cenarion, en Silithus, quiere que consigas 8 fragmentos de tablilla Crepuscular.", objs={"Fragmentos de tablilla Crepuscular"}},
    [8285] = {n="El desertor", d="Lleva la tablilla restaurada a Ermitaño Ortell en Silithus."},
    [8318] = {n="Mensajes secretos", d="Lleva 10 textos Crepusculares codificados a Bor Ferocrín en el Fuerte Cenarion.", tgo={{"Guardián Crepuscular Havunth", "Vengador Crepuscular", "Geoseñor Crepuscular", "Clamapiedras Crepuscular", "Maestro Crepuscular", "Señor Crepuscular Everun", "Flamatracador Crepuscular", "Señor supremo Crepuscular"}}},
    [8365] = {n="¡Sombreros de pirata a babor!", d="La modista Jactancia quiere que reúnas 20 sombreros de pirata de los Mares del Sur y que se los lleves al Puerto Bonvapor de Tanaris.", tgo={{"Pirata de los Mares del Sur", "Filibustero de los Mares del Sur", "Portuario de los Mares del Sur", "Espadachín de los Mares del Sur", "Andre Barbafuego", "Kregg Volcayecto"}}},
    [8366] = {n="Mamporros en los Mares del Sur", d="El jefe de seguridad Pasaquillas del Puerto Bonvapor de Tanaris quiere que mates a 10 piratas de los Mares del Sur, 10 filibusteros de los Mares del Sur, 10 portuarios de los Mares del Sur y 10 espadachines de los Mares del Sur.", tgo={{"Pirata de los Mares del Sur"}, {"Filibustero de los Mares del Sur"}, {"Portuario de los Mares del Sur"}, {"Espadachín de los Mares del Sur"}}},
    [8411] = {n="Dominar los elementos", d="Lleva los elementos tierra, aire, fuego y agua a Bath'rah el Vigía del viento.", tgo={{"Demonio del polvo", "Exiliado tronador", "Ciclonio", "Vórtice ráfaga", "Vórtice espiral", "Tormenta viviente", "Desgarrador espirálico", "Caminatormentas espirálico"}, {"Elemental de roca", "Furia pétrea", "Esclavo elemental", "Exiliado resonador", "Elemental de roca inferior", "Elemental de roca superior", "Estruendor", "Myzrael"}, {"Embajador Infernus", "Exiliado ardiente", "Espíritu flameante huido", "Devastador ardiente", "Destructor ardiente", "Elemental llameante", "Elemental del infierno", "Elemental de magma"}, {"Elemental de agua inferior", "Éxilu coronador", "Guardián invocado", "Elemental de agua podrida", "Sirviente Aku'mai", "Elemental de mar", "Rocío del mar", "Horror irradiado"}}},
    [8412] = {n="Tótem de espíritu", d="Lleva lo necesario para el tótem del espíritu a Bath'rah el Vigía del viento.", tgo={{"Buitre carroñero", "Rondador carroñero", "Rondador Brumatósigo", "Rondador de peste", "Rotting Condor", "Buitre Alapeste"}, {"Buitre carroñero", "Oso negro malsano", "Oso pardo malsano", "Rotting Condor", "Buitre Alapeste"}}},
