    [8422] = {n="Plumas de trol", d="Reúne un total de 6 plumas vudú en el Templo Sumergido.", tgo={{"Gasher", "Zul'Lor", "Gasher"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loh'ro", "Loh'ro"}}, star={"Cosechador de almas", {"WARLOCK"}}},
    [8423] = {n="Parentesco guerrero", d="Mata a 7 jabinfernos de Las Tierras Devastadas y vuelve junto al héroe caído de la Horda.", tgo={{"Jabinferno"}}},
    [8424] = {n="La guerra contra los Sombra Jurada", d="Acaba con los Sombra Jurada en Las Tierras Devastadas y regresa junto al héroe caído de la Horda.", tgo={{"Adepto Sombra Jurada"}, {"Cultor Sombra Jurada"}, {"Matón Sombra Jurada"}}},
    [8425] = {n="Plumas Vudú", d="Llévale las plumas vudú de los trols del Templo Sumergido al héroe caído de la Horda.", tgo={{"Gasher", "Zul'Lor", "Gasher"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loh'ro", "Loh'ro"}}, star={"Frasco de diamante", {"WARRIOR"}}},
    [8460] = {n="Aliado a los Fauces de Madera", d="Grazle quiere que demuestres tu valía matando a 6 guerreros Muertobosque, 6 abrecaminos Muertobosque y 6 jardineros Muertobosque. Cuando lo hayas hecho, vuelve con él al sur de Frondavil, cerca del Santuario Esmeralda.", tgo={{"Guerrero Muertobosque"}, {"Abrecaminos Muertobosque"}, {"Jardinero Muertobosque"}}},
    [8461] = {n="Los Muertobosque del Norte", d="Nafien quiere que mates a 6 vigías del cubil Muertobosque, 6 vengadores Muertobosque y 6 chamanes Muertobosque. Luego, vuelve a buscarlo al norte de Frondavil, cerca de la entrada del Bastión Fauces de Madera.", tgo={{"Vigía del cubil Muertobosque"}, {"Vengador Muertobosque"}, {"Chamán Muertobosque"}}},
    [8462] = {n="Habla con Nafien", d="Viaja hacia el norte por el camino principal de Frondavil y habla con el fúrbolg Nafien. Está haciendo guardia en la entrada del Bastión Fauces de Madera."},
    [8464] = {n="Actividad de los Nevada", d="Salfa quiere que mates 8 chamanes Nevada, 8 vigías del cubil Nevada y 8 ursas Nevada. Salfa está a las puertas del Bastión Fauces de Madera en Cuna del Invierno.", tgo={{"Chamán Nevada"}, {"Vigía del cubil Nevada"}, {"Ursa Nevada"}}},
    [8465] = {n="Habla con Salfa", d="Viaja por el Bastión Fauces de Madera y sal a Cuna del Invierno. Habla con Salfa, que está haciendo guardia en la entrada del Bastión Fauces de Madera."},
