    [9051] = {n="Prueba de toxicidad", d="Clávale la púa de demosaurio a un demosaurio. Ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro cuando hayas completado tu tarea."},
    [9052] = {n="Veneno de Sangrepétalo", d="Reúne 8 champiñones de sangre y 8 aguijones Gorishi, y ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro.", tgo={{"Avispa Gorishi", "Aguijonero Gorishi"}, {}}, objs={"Brote Sangrepétalo"}},
    [9053] = {n="Un ingrediente mejor", d="Consigue una vid pútrida de las que custodia el guardián en las profundidades del Templo Sumergido y después ve a ver de nuevo a Torwa Abrecaminos.", tgo={{"Atal'alarion"}}, star={"Pelambre grisácea", {"DRUID"}}},
    [65593] = {n="Corazón de los amantes", d="Lleva el corazón de Avelina Lilly e Isaac Pearson a Carendin Halgar en el Templo de los Condenados.", tgo={{"Avelina Lilly"}, {"Isaac Pearson"}}},
