    [96897] = {n="El Culto de los Malditos", d="Mata a 8 neófitos oscuros y 8 déspotas oscuros en Claros de Tirisfal.", tgo={{"Neófito oscuro"}, {"Déspota oscuro"}}},
    [96898] = {n="Los restos de la guerra", d="Recoge 12 trozos de cristal necrótico en Claros de Tirisfal.", tgo={{"Neófito oscuro", "Déspota oscuro"}}},
    [96899] = {n="Fuerte de Bandarion", d="Habla con Leonid Barthalomew en el Fuerte de Bandarion en Claros de Tirisfal."},
    [96984] = {n="El corazón de la perturbación", d="Recoge motas arcanas en la Ciudad de Dalaran y dáselas a Magus Wordeen Vacuamirada, en Molino Tarren."},
    [96986] = {n="El Caballero de la tumba", d="Asesina a Atrexis, el Caballero de la tumba en la Ciudad de Dalaran para Melisara, en el Molino Tarren."},
    [96987] = {n="Educación oportunista", d="Recoge la Fundación de Dalaran de la Ciudad de Dalaran y dáselo a Rexxie Cuprigarra cerca de la entrada de la cloaca."},
    [96988] = {n="Origen del poder", d="Recoge 6 núcleos de avizor rajados en la Ciudad de Dalaran y dáselos al Doctor Martin Felben en Entrañas.", objs={"Fragmented Sentry"}},
    [97022] = {n="Report to Danitha", d="Speak with Danitha Morr at Bandarion Keep."},
    [97049] = {n="Essence of Seeping Slimes", d="Gather 8 Seeping Slime Essence in the Shaper's Terrace."},
    [97196] = {n="Ojo del Gélido", d="Recupera el Ojo del Gélido de Zahúrda Rajacieno."},
    [97198] = {n="Blackmaw Magic", d="Recover a Blackmaw Ritual Totem from Blackmaw Hold."},
    [97223] = {n="Matriarca Garrasangre", d="Llévale huevos de la Matriarca Garrasangre a Xar'Ti en el Poblado Sen'jin.", tgo={{"Matriarca Garrasangre"}}},
    [97225] = {n="Ídolos loa olvidados", d="Recoge 8 ídolos loa olvidados en las Islas del Eco. Llévaselos al Maestro Gadrin en el Poblado Sen'jin.", objs={"Ídolo loa olvidado"}},
    [97243] = {n="El llamado del fuego", d="Lleva la antorcha de la Llama Latente a Olariaan Fuegoveloz en el Santuario de las Llamas, en los Bajíos Ventobaya."},
    [97244] = {n="El llamado del fuego", d="Mata al sacerdocielo Faladiel en los Bajíos Ventobaya y recoge su corazón.", tgo={{"Sacerdocielo Faladiel"}}},
    [97245] = {n="El llamado del fuego", d="Encuentra el hogar de Kuramaa en las Tierras Altas de Shen'dar y derrota al espíritu en combate. Llévale la máscara de Kuramaa a Olariaan Fuegoveloz en los Bajíos Ventobaya, cuando hayas salido victorioso.", tgo={{"Kuramaa"}}},
    [97250] = {n="Falsa acusación, justa redención", d="Mata a los soldados de la Alianza que están usurpando Los Baldíos en la frontera de Marjal Revolcafango. Luego, regresa con Bruto Logmar en el Campamento Taurajo.", tgo={{"Soldado invasor"}, {"Saqueador indignado"}}},
    [97253] = {n="Partes y piezas", d="Recoge 5 puñados de piezas complicadas en la zona superior del campamento pirata ubicado al sur de Trinquete. Luego, regresa con Desdio el Desdichado en Trinquete.", objs={"Montón de piezas complicadas"}},
    [97257] = {n="El llamado del fuego", d="Espera a que Olariaan comience el ritual en el blandón de ofrenda y sigue sus instrucciones.\nDebes llevar la llama eterna a Valanaar antes de que se acabe el tiempo.", tgo={{"Blandón de ofrenda"}, {"Blandón de la llama eterna"}}, star={"Tótem de llamas cargadas", {"SHAMAN"}}},
    [97265] = {n="Odio a los Odio Feroz", d="Elimina distintos sátiros Odio Feroz en Sargeron en Desolace y luego regresa con Aka'rai en la Aldea Cazasombras.", tgo={{"Tramposo Odio Feroz"}, {"Clamainferno Odio Feroz"}, {"Acechasombras Odio Feroz"}, {"Jurapenas Odio Feroz"}, {"Pícaro Odio Feroz"}}},
    [97279] = {n="Armas extraviadas", d="Reúne 6 armas de entrenamiento abandonadas y devuélveselas a Kzan Trallafusta en El Cubil.", objs={"Arma de entrenamiento abandonada"}},
    [97281] = {n="Una tormenta inminente", d="Llévale el orbe opaco tormentoso a Rezlak cerca del Barranco Árido."},
    [97282] = {n="Potencial tormentoso", d="Llévale 5 órganos de truenagarto cargados a Rezlak cerca del Barranco Árido.", tgo={{"Truenagarto", "Lomorrayo", "Halikor"}}},
    [97287] = {n="Negociaciones arteras", d="Habla con la imagen de la archimaga Modera cerca de Dalaran."},
    [97288] = {n="Tormento eterno", d="Entrega la cabeza abominable al maestro boticario Faranell en Entrañas."},
    [97289] = {n="Tormento eterno", d="Lleva la cabeza del Barón al cuerpo de Othmar en Entrañas."},
    [97290] = {n="Tormento eterno", d="Informa tus hallazgos al maestro boticario Faranell en Entrañas."},
    [97291] = {n="Tormento eterno", d="Visita a Tawny Grisette en el Barrio del Comercio para conseguir un capacete tóxico, a las instructoras de herboristería para reunir hierba ampolla y a los vendedores de venenos del Barrio de los Pícaros para obtener esencia de agonía. Lleva todo al maestro boticario Faranell de Entrañas.", objs={"Hierba ampolla"}},
    [97292] = {n="Tormento eterno", d="Inyecta el suero siseante en el sistema que está encima del cuerpo de Othmar para el maestro boticario Faranell.", objs={"Othmar's Head"}},
    [97327] = {n="Blackmaw Pouches", d="Botín de: Blackmaw Berserker, Blackmaw Thrall, Blackmaw Headhunter", tgo={{"Blackmaw Berserker", "Blackmaw Thrall", "Blackmaw Headhunter", "Swarming Imp", "Legashi Slayer", "Blackmaw Champion"}}},
    [97328] = {n="Todo lo que tenga valor", d="Recupera 8 cargamentos robados de las Ruinas de Zul'Kunda en Vega de Tuercespina y entrégale tu botín a alguien en Bahía del Botín."},
    [97329] = {n="Where's the Key?", d="Botín de: Explorador Sangrapellejo, Cazador Sangrapellejo, Rabioso Sangrapellejo", tgo={{"Explorador Sangrapellejo", "Cazador Sangrapellejo", "Rabioso Sangrapellejo", "Médico brujo Sangrapellejo", "Rebanacabezas Sangrapellejo", "Maestro de bestias Sangrapellejo", "Místico Sangrapellejo"}}},
    [97331] = {n="Zimmix's Great Escape", d="Escort Zimmix Sputterspark away from the Ruins of Zul'Kunda then tell Wharfmaster Lozgil in Booty Bay of your successful rescue."},
    [97332] = {n="Twice Misplaced Trust", d="Deliver the Twice Reordered Package to Wharfmaster Whizzbuzz at Powderfuse Port in the Riverglades."},
    [97386] = {n="El ataque de Grom'gol", d="<name> comandante Aggro'gosh del Campamento Grom'gol quiere que mates a los ogros en el Túmulo Ogro Mosh'Ogg.", tgo={{"Creaconjuros Mosh'Ogg"}, {"Belicista Mosh'Ogg"}, {"Aplastador Mosh'Ogg"}, {"Chamán Mosh'Ogg"}}},
    [97453] = {n="Malezas erradicadas", d="Mata 6 malezas carnívoras al sur de Grom'gol y luego informa a la madre de Gemmil.", tgo={{"Hierba carnívora"}}},
    [97485] = {n="Tradiciones de la Cima", d="Cómprale un fardo de hierbas a Nida, la herborista; un fardo de ramitas de cedro a Nata, la proveedora de encantamiento; un hilo de tendón a Mahu, el proveedor de peletería; y sílex y yesca ceremoniales a Naal, el proveedor de cocina.\nCombina estos objetos y esparce el incienso por el Alto de los Cazadores.", objs={"Quemador de incienso"}},
    [97530] = {n="Dunemaul Dues", d="Botín de: Ogro Machacaduna, Déspota Machacaduna, Magro ogro Machacaduna", tgo={{"Ogro Machacaduna", "Déspota Machacaduna", "Magro ogro Machacaduna", "Tosco Machacaduna", "Brujo Machacaduna"}}},
