    [97558] = {n="Pellejos para los Renegados", d="Lleva 8 membranas de alas de murciumbrío, 6 pellejos de can oscuro y 3 pieles de múrloc Anca Vil a Shelene Rhobart.", tgo={{"Murciumbrío superior", "Murciumbrío vampírico"}, {"Can oscuro decrépito", "Can oscuro maldito"}, {"Oráculo menor Anca Vil", "Habitabosta Anca Vil"}}},
    [97908] = {n="Campamento básico: Desuello", d="Habla con Thuwd en Orgrimmar para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", tgo={{"Thuwd"}}},
    [97936] = {n="Campamento básico: Desuello", d="Habla con Yonn Corte Profundo en Poblado Pezuña de Sangre para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", tgo={{"Yonn Corte Profundo"}}},
