    [98341] = {n="El gran espíritu felino natoviento", d="Busca el avatar de Saeyleenan en la parte sur de Claro de la Luna y aprende sobre la naturaleza del felino natoviento."},
    [98342] = {n="El gran espíritu felino", d="Recupera la reliquia del colmillo, la reliquia de la garra y la reliquia de la sombra silenciosa del Túmulo de Tempestira, y devuélvelas al Gran espíritu felino.", objs={"Reliquia del colmillo", "Reliquia de la garra", "Reliquia de la sombra silenciosa"}},
