    [98389] = {n="Una luz en la oscuridad", d="Libera 6 víctimas enredadas en Hondonada de Redes de la Noche y vuelve con Aramis Manomartillo en Camposanto."},
    [98404] = {n="El gran espíritu felino natoviento", d="Recupera la reliquia del colmillo, la reliquia de la garra y la reliquia de la sombra silenciosa del Túmulo de Tempestira, y devuélvelas al Avatar de Saeyleenan.", objs={"Reliquia del colmillo", "Reliquia de la garra", "Reliquia de la sombra silenciosa"}},
